    private static final class InventorySlot {
        String itemId = "";
        String displayName = "";
        int quantity = 0;
        int maxStack = 99;
        String sourceObjectName = "";
        String sourceBehaviorTreeProfileName = "";
        boolean useObjAsIcon = true;
        String customIconPath = "";
        transient Texture customIconTexture;
        transient String customIconTexturePath = "";

        // Runtime-only, renderable duplicate of the world object used when no
        // custom inventory icon is supplied.  This is deliberately a
        // SpawnedObject clone rather than a second model-only preview so the
        // inventory copy carries the object's complete mesh/material state.
        transient SpawnedObject objectIconClone;
        transient String objectIconCloneSourceName = "";

        boolean isEmpty() {
            return itemId == null || itemId.trim().isEmpty() || quantity <= 0;
        }

        void clear() {
            itemId = "";
            displayName = "";
            quantity = 0;
            maxStack = 99;
            sourceObjectName = "";
            sourceBehaviorTreeProfileName = "";
            useObjAsIcon = true;
            customIconPath = "";
            customIconTexture = null;
            customIconTexturePath = "";
            objectIconClone = null;
            objectIconCloneSourceName = "";
        }
    }
    private final ArrayList<InventorySlot> playerInventory = new ArrayList<>();

    private synchronized void ensureInventoryCapacityInternal(int capacity){
        capacity=Math.max(1,Math.min(60,capacity));
        while(playerInventory.size()<capacity)playerInventory.add(new InventorySlot());
        while(playerInventory.size()>capacity)playerInventory.remove(playerInventory.size()-1);
        playerInventoryCapacity=capacity;
        selectedInventorySlot=Math.max(0,Math.min(selectedInventorySlot,capacity-1));
    }
    public synchronized void setInventoryCapacity(int capacity){
        capacity=Math.max(1,Math.min(60,capacity));
        if(capacity<playerInventory.size())for(int i=capacity;i<playerInventory.size();i++)if(!playerInventory.get(i).isEmpty())return;
        ensureInventoryCapacityInternal(capacity);
    }
    /** Adds as much as possible and returns the amount actually added. */
    public synchronized int addInventoryItem(String itemId, String displayName, int quantity, int maxStack) {
        return addInventoryItemInternal(itemId, displayName, quantity, maxStack,
                "", "", true, "");
    }

    private synchronized int addInventoryItemFromObject(SpawnedObject object, int quantity) {
        if (object == null || object.isLightSource) return 0;
        String itemId = object.inventoryItemId == null || object.inventoryItemId.trim().isEmpty()
                ? object.objectName : object.inventoryItemId.trim();
        // Inventory presentation is driven exclusively by the explicitly assigned
        // Item -> Display Name. Never derive an inventory name from an asset filename
        // or internal item ID.
        String itemName = object.inventoryItemName == null
                ? "" : object.inventoryItemName.trim();
        int amount = Math.max(1, quantity);
        String customIcon = object.inventoryItemCustomIconPath == null
                ? "" : object.inventoryItemCustomIconPath.trim();
        boolean useObjectCopy = object.inventoryItemUseObjAsIcon || customIcon.isEmpty();
        return addInventoryItemInternal(itemId, itemName, amount, object.inventoryItemMaxStack,
                getBehaviorTreeObjectName(object, spawnedObjects.indexOf(object)),
                object.behaviorTreeProfileName == null ? "" : object.behaviorTreeProfileName,
                useObjectCopy, customIcon);
    }

    private synchronized int addInventoryItemInternal(String itemId, String displayName, int quantity,
                                                       int maxStack, String sourceObjectName,
                                                       String sourceBehaviorTreeProfileName,
                                                       boolean useObjAsIcon, String customIconPath) {
        if (itemId == null || itemId.trim().isEmpty() || quantity <= 0) return 0;
        ensureInventoryCapacityInternal(playerInventoryCapacity);
        String id = itemId.trim();
        String name = displayName == null ? "" : displayName.trim();
        int limit = Math.max(1, Math.min(9999, maxStack));
        int remaining = quantity;

        for (InventorySlot slot : playerInventory) {
            if (!slot.isEmpty() && id.equalsIgnoreCase(slot.itemId) && slot.quantity < slot.maxStack) {
                int add = Math.min(remaining, slot.maxStack - slot.quantity);
                slot.quantity += add;
                remaining -= add;
                if (remaining <= 0) return quantity;
            }
        }

        for (InventorySlot slot : playerInventory) {
            if (slot.isEmpty()) {
                int add = Math.min(remaining, limit);
                slot.itemId = id;
                slot.displayName = name;
                slot.quantity = add;
                slot.maxStack = limit;
                slot.sourceObjectName = sourceObjectName == null ? "" : sourceObjectName.trim();
                slot.sourceBehaviorTreeProfileName = sourceBehaviorTreeProfileName == null ? "" : sourceBehaviorTreeProfileName.trim();
                slot.useObjAsIcon = useObjAsIcon;
                slot.customIconPath = customIconPath == null ? "" : customIconPath;
                slot.customIconTexture = null;
                slot.customIconTexturePath = "";
                slot.objectIconClone = null;
                slot.objectIconCloneSourceName = "";
                remaining -= add;
                if (remaining <= 0) return quantity;
            }
        }
        return quantity - remaining;
    }

    public synchronized int getInventoryItemQuantity(String itemId){int total=0;if(itemId==null||itemId.trim().isEmpty())return 0;for(InventorySlot slot:playerInventory)if(!slot.isEmpty()&&itemId.equalsIgnoreCase(slot.itemId))total+=slot.quantity;return total;}
    public synchronized boolean hasInventoryItem(String itemId,int quantity){return getInventoryItemQuantity(itemId)>=Math.max(1,quantity);}
    public synchronized int removeInventoryItem(String itemId,int quantity){if(itemId==null||itemId.trim().isEmpty()||quantity<=0)return 0;int remaining=quantity;for(InventorySlot slot:playerInventory)if(!slot.isEmpty()&&itemId.equalsIgnoreCase(slot.itemId)){int remove=Math.min(remaining,slot.quantity);slot.quantity-=remove;remaining-=remove;if(slot.quantity<=0)slot.clear();if(remaining<=0)break;}return quantity-remaining;}
    public synchronized boolean consumeSelectedInventoryItem(){if(selectedInventorySlot<0||selectedInventorySlot>=playerInventory.size())return false;InventorySlot slot=playerInventory.get(selectedInventorySlot);if(slot.isEmpty())return false;slot.quantity--;if(slot.quantity<=0)slot.clear();return true;}
    public synchronized void clearPlayerInventory(){playerInventory.clear();ensureInventoryCapacityInternal(playerInventoryCapacity);selectedInventorySlot=0;}
    public synchronized String getSelectedInventoryItemId(){if(selectedInventorySlot<0||selectedInventorySlot>=playerInventory.size())return "";InventorySlot slot=playerInventory.get(selectedInventorySlot);return slot.isEmpty()?"":slot.itemId;}
    private static String encodeInventoryString(String v){if(v==null)v="";return Base64.getEncoder().encodeToString(v.getBytes(java.nio.charset.StandardCharsets.UTF_8));}
    private static String decodeInventoryString(String v){if(v==null||v.isEmpty())return "";try{return new String(Base64.getDecoder().decode(v),java.nio.charset.StandardCharsets.UTF_8);}catch(Exception e){return v;}}
    private synchronized void saveInventoryToProperties(Properties p,String prefix){p.setProperty(prefix+"capacity",Integer.toString(playerInventoryCapacity));p.setProperty(prefix+"selected",Integer.toString(selectedInventorySlot));int count=0;for(InventorySlot slot:playerInventory)if(!slot.isEmpty())count++;p.setProperty(prefix+"items.count",Integer.toString(count));int n=0;for(int i=0;i<playerInventory.size();i++){InventorySlot slot=playerInventory.get(i);if(slot.isEmpty())continue;String k=prefix+"items."+n+".";p.setProperty(k+"slot",Integer.toString(i));p.setProperty(k+"id",encodeInventoryString(slot.itemId));p.setProperty(k+"name",encodeInventoryString(slot.displayName));p.setProperty(k+"quantity",Integer.toString(slot.quantity));p.setProperty(k+"maxStack",Integer.toString(slot.maxStack));
            p.setProperty(k+"sourceObject",encodeInventoryString(slot.sourceObjectName));
            p.setProperty(k+"sourceBehaviorTree",encodeInventoryString(slot.sourceBehaviorTreeProfileName));
            p.setProperty(k+"useObjAsIcon",Boolean.toString(slot.useObjAsIcon));
            p.setProperty(k+"customIcon",encodeInventoryString(slot.customIconPath));
            n++;}}
    private synchronized void loadInventoryFromProperties(Properties p,String prefix){int cap=Math.max(1,Math.min(60,projectInt(p,prefix+"capacity",12)));playerInventory.clear();ensureInventoryCapacityInternal(cap);int count=Math.max(0,Math.min(cap,projectInt(p,prefix+"items.count",0)));for(int i=0;i<count;i++){String k=prefix+"items."+i+".";int idx=Math.max(0,Math.min(cap-1,projectInt(p,k+"slot",i)));InventorySlot slot=playerInventory.get(idx);slot.itemId=decodeInventoryString(p.getProperty(k+"id",""));slot.displayName=decodeInventoryString(p.getProperty(k+"name",""));slot.quantity=Math.max(0,projectInt(p,k+"quantity",0));slot.maxStack=Math.max(1,Math.min(9999,projectInt(p,k+"maxStack",99)));
            slot.sourceObjectName=decodeInventoryString(p.getProperty(k+"sourceObject",""));
            slot.sourceBehaviorTreeProfileName=decodeInventoryString(p.getProperty(k+"sourceBehaviorTree",""));
            slot.useObjAsIcon=Boolean.parseBoolean(p.getProperty(k+"useObjAsIcon","true"));
            slot.customIconPath=decodeInventoryString(p.getProperty(k+"customIcon",""));
            if(slot.itemId.trim().isEmpty()||slot.quantity<=0)slot.clear();}selectedInventorySlot=Math.max(0,Math.min(cap-1,projectInt(p,prefix+"selected",0)));}
