    private static final float PROJECTILE_SPEED = 0.34f;
    private static final float PROJECTILE_LIFETIME_SECONDS = 3.0f;
    private static final float PROJECTILE_HIT_RADIUS = 0.55f;

    private static final class Projectile {
        private final OBJModel model;
        private final Texture texture;
        private final float scale;
        private final boolean fallbackCircle;
        private float x, y, z;
        private final float dx, dz;
        private float age = 0.0f;
        private final int damage;

        Projectile(OBJModel model, Texture texture, float scale, float x, float y, float z,
                   float dx, float dz, int damage) {
            this.model = model;
            this.texture = texture;
            this.scale = Math.max(0.01f, scale);
            this.fallbackCircle = (model == null);
            this.x = x; this.y = y; this.z = z;
            this.dx = dx; this.dz = dz;
            this.damage = Math.max(0, damage);
        }

        void update(float dt) {
            x += dx * PROJECTILE_SPEED;
            z += dz * PROJECTILE_SPEED;
            age += dt;
        }

        boolean expired() { return age >= PROJECTILE_LIFETIME_SECONDS; }

        void render(GL2 gl) {
            gl.glPushMatrix();
            gl.glTranslatef(x, y, z);

            if (fallbackCircle) {
                // No custom OBJ was selected: render a small, solid grey circle.
                // The circle is oriented perpendicular to the projectile's travel
                // direction so it remains visually readable while moving forward.
                gl.glPushAttrib(GL2.GL_ENABLE_BIT | GL2.GL_COLOR_BUFFER_BIT |
                        GL2.GL_TEXTURE_BIT | GL2.GL_LIGHTING_BIT);
                gl.glDisable(GL2.GL_TEXTURE_2D);
                gl.glDisable(GL2.GL_LIGHTING);
                gl.glColor3f(0.58f, 0.58f, 0.58f);

                float radius = Math.max(0.10f, scale * 0.75f);
                float sideX = dz;
                float sideZ = -dx;
                float sideLength = (float) Math.sqrt(sideX * sideX + sideZ * sideZ);
                if (sideLength < 0.0001f) {
                    sideX = 1.0f;
                    sideZ = 0.0f;
                    sideLength = 1.0f;
                }
                sideX /= sideLength;
                sideZ /= sideLength;

                final int segments = 20;
                gl.glBegin(GL2.GL_TRIANGLE_FAN);
                gl.glVertex3f(0.0f, 0.0f, 0.0f);
                for (int i = 0; i <= segments; i++) {
                    double angle = (Math.PI * 2.0 * i) / segments;
                    float px = (float) Math.cos(angle) * radius;
                    float py = (float) Math.sin(angle) * radius;
                    gl.glVertex3f(sideX * px, py, sideZ * px);
                }
                gl.glEnd();

                gl.glPopAttrib();
                gl.glPopMatrix();
                return;
            }

            gl.glScalef(scale, scale, scale);
            gl.glColor3f(1f, 1f, 1f);
            if (texture != null) { texture.bind(gl); gl.glEnable(GL2.GL_TEXTURE_2D); }
            else gl.glDisable(GL2.GL_TEXTURE_2D);
            model.render(gl);
            gl.glDisable(GL2.GL_TEXTURE_2D);
            gl.glPopMatrix();
        }
    }

    // ============================================================
    // SHADER-BASED MATERIAL PASS
    // ============================================================
    // Compatibility-profile GLSL is used so the existing OBJ display lists,
    // fixed-function camera setup, and scene lights continue to work. The
    // shader reads the existing OBJ UVs/normals and adds true normal,
    // metallic, and roughness texture response when those maps are present.
    private static int materialShaderProgram = 0;
    private static int materialShaderBaseColor = -1;
    private static int materialShaderNormal = -1;
    private static int materialShaderMetallic = -1;
    private static int materialShaderRoughness = -1;
    private static int materialShaderEmission = -1;
    private static int materialShaderHasBaseColor = -1;
    private static int materialShaderHasTransparency = -1;
    private static int materialShaderHasNormal = -1;
    private static int materialShaderHasMetallic = -1;
    private static int materialShaderHasRoughness = -1;
    private static int materialShaderHasEmission = -1;
    private static int materialShaderMetallicValue = -1;
    private static int materialShaderRoughnessValue = -1;
    private static int materialShaderSpecular = -1;
    private static int materialShaderShininess = -1;
    private static int materialShaderFogEnabled = -1;
    private static int materialShaderFogDensity = -1;
    private static int materialShaderFogColor = -1;

    private static final String MATERIAL_VERTEX_SHADER =
            "#version 120\n" +
            "varying vec3 vEyePosition;\n" +
            "varying vec3 vEyeNormal;\n" +
            "varying vec2 vTexCoord;\n" +
            "void main(){\n" +
            "  vec4 eyePos = gl_ModelViewMatrix * gl_Vertex;\n" +
            "  vEyePosition = eyePos.xyz;\n" +
            "  vEyeNormal = normalize(gl_NormalMatrix * gl_Normal);\n" +
            "  vTexCoord = gl_MultiTexCoord0.st;\n" +
            "  gl_FrontColor = gl_Color;\n" +
            "  gl_Position = ftransform();\n" +
            "}\n";

    private static final String MATERIAL_FRAGMENT_SHADER =
            "#version 120\n" +
            "uniform sampler2D uBaseColor;\n" +
            "uniform sampler2D uNormalMap;\n" +
            "uniform sampler2D uMetallicMap;\n" +
            "uniform sampler2D uRoughnessMap;\n" +
            "uniform sampler2D uEmissionMap;\n" +
            "uniform bool uHasBaseColor;\n" +
            "uniform bool uHasTransparency;\n" +
            "uniform bool uHasNormal;\n" +
            "uniform bool uHasMetallic;\n" +
            "uniform bool uHasRoughness;\n" +
            "uniform bool uHasEmission;\n" +
            "uniform float uMetallicValue;\n" +
            "uniform float uRoughnessValue;\n" +
            "uniform float uSpecular;\n" +
            "uniform float uShininess;\n" +
            "uniform bool uFogEnabled;\n" +
            "uniform float uFogDensity;\n" +
            "uniform vec3 uFogColor;\n" +
            "varying vec3 vEyePosition;\n" +
            "varying vec3 vEyeNormal;\n" +
            "varying vec2 vTexCoord;\n" +
            "void main(){\n" +
            "  vec4 baseSample = uHasBaseColor ? texture2D(uBaseColor, vTexCoord) : vec4(1.0);\n" +
            "  if(uHasTransparency && baseSample.a < 0.02) discard;\n" +
            "  vec3 baseColor = clamp(baseSample.rgb * gl_Color.rgb, 0.0, 1.0);\n" +
            "  vec3 N = normalize(vEyeNormal);\n" +
            "  if(uHasNormal){\n" +
            "    vec3 q1 = dFdx(vEyePosition);\n" +
            "    vec3 q2 = dFdy(vEyePosition);\n" +
            "    vec2 st1 = dFdx(vTexCoord);\n" +
            "    vec2 st2 = dFdy(vTexCoord);\n" +
            "    float det = st1.x * st2.y - st1.y * st2.x;\n" +
            "    vec3 T = q1 * st2.y - q2 * st1.y;\n" +
            "    vec3 B = q2 * st1.x - q1 * st2.x;\n" +
            "    if(abs(det) > 0.00001){ T /= det; B /= det; }\n" +
            "    T = normalize(T - N * dot(N,T));\n" +
            "    B = normalize(cross(N,T));\n" +
            "    vec3 mapped = texture2D(uNormalMap, vTexCoord).xyz * 2.0 - 1.0;\n" +
            "    float mappedLen = max(length(mapped), 0.0001);\n" +
            "    mapped /= mappedLen;\n" +
            "    N = normalize(T * mapped.x + B * mapped.y + N * mapped.z);\n" +
            "  }\n" +
            "  float metallic = uHasMetallic ? texture2D(uMetallicMap,vTexCoord).r : uMetallicValue;\n" +
            "  float roughness = uHasRoughness ? texture2D(uRoughnessMap,vTexCoord).r : uRoughnessValue;\n" +
            "  metallic = clamp(metallic,0.0,1.0);\n" +
            "  roughness = clamp(roughness,0.0,1.0);\n" +
            "  vec3 result = baseColor * 0.12 * (1.0 - 0.45 * metallic);\n" +
            "  vec3 V = normalize(-vEyePosition);\n" +
            "  for(int i=0;i<8;i++){\n" +
            "    if(gl_LightSource[i].diffuse.a <= 0.0) continue;\n" +
            "    vec3 L;\n" +
            "    float attenuation = 1.0;\n" +
            "    if(gl_LightSource[i].position.w == 0.0){\n" +
            "      L = normalize(gl_LightSource[i].position.xyz);\n" +
            "    } else {\n" +
            "      vec3 toLight = gl_LightSource[i].position.xyz - vEyePosition;\n" +
            "      float dist = length(toLight);\n" +
            "      L = toLight / max(dist,0.0001);\n" +
            "      attenuation = 1.0 / max(gl_LightSource[i].constantAttenuation + gl_LightSource[i].linearAttenuation * dist + gl_LightSource[i].quadraticAttenuation * dist * dist, 0.0001);\n" +
            "    }\n" +
            "    float NdotL = max(dot(N,L),0.0);\n" +
            "    vec3 H = normalize(L+V);\n" +
            "    float NdotH = max(dot(N,H),0.0);\n" +
            "    float exponent = max(2.0, uShininess * (1.05 - roughness));\n" +
            "    float specTerm = pow(NdotH, exponent) * uSpecular * (0.15 + 0.85 * (1.0 - roughness));\n" +
            "    float diffuseTerm = 0.16 + NdotL * (1.0 - 0.18 * metallic);\n" +
            "    float reflected = specTerm * (0.35 + 0.65 * metallic);\n" +
            "    vec3 lit = baseColor * diffuseTerm * (1.0 - 0.45 * metallic) + vec3(reflected);\n" +
            "    result += (lit - baseColor * 0.12 * (1.0 - 0.45 * metallic)) * gl_LightSource[i].diffuse.rgb * attenuation;\n" +
            "  }\n" +
            "  if(uHasEmission) result += texture2D(uEmissionMap,vTexCoord).rgb * 0.8;\n" +
            "  if(uFogEnabled){ float d = length(vEyePosition); float f = clamp(exp(-uFogDensity * uFogDensity * d * d), 0.0, 1.0); result = mix(uFogColor, result, f); }\n" +
            "  gl_FragColor = vec4(max(result,vec3(0.0)), baseSample.a * gl_Color.a);\n" +
            "}\n";

    private static boolean materialShaderAvailable() {
        return materialShaderProgram != 0;
    }

