    // True while restoring saved WGANIM selections from a project/scene.
    // Programmatic combo changes must not overwrite the authoritative extracted
    // project paths with a same-named file from the global WGANIM library.
    private volatile boolean restoringPlayerAnimationSelections = false;
    // WGAnim profile attached to the active project/scene. The profile owns
    // the four canonical states; these existing paths remain the runtime cache.
    private String playerWGAnimProfileName = "";
    private final Properties wganimProfileProperties = new Properties();
    private volatile String pendingPlayerIdleAnimationPath = null;
    private volatile String pendingPlayerMovementAnimationPath = null;
