    // ============================================================
    // HEIGHTMAP TERRAIN
    // ============================================================

    // Heightmaps are kept as a dedicated terrain runtime instead of being
    // converted into a normal OBJ SpawnedObject.  This prevents the previous
    // blank-object failure and gives the stage a real height field for player
    // grounding, player-start placement, and material painting.
    private volatile HeightmapTerrainRuntime activeHeightmapTerrain;
    // Water is a completely separate runtime entity. Its geometry is built only
    // from the serialized black-cell mask and never shares the heightmap terrain
    // material ranges/textures.
    private volatile WaterTerrainRuntime activeHeightmapWater;
    private volatile Heightmaps.HeightmapStageData currentHeightmapStageData;
    private volatile Heightmaps.HeightmapStageData pendingHeightmapStageData;

    // World/Environment terrain material brush. The brush operates directly on
    // the active heightmap terrain; Heightmaps.java remains responsible only
    // for loading/generating the heightfield and its serialized material data.
    private volatile boolean terrainMaterialBrushEnabled = false;
    private volatile int terrainMaterialBrushX = -1;
    private volatile int terrainMaterialBrushY = -1;
    private volatile boolean terrainMaterialBrushPaintPending = false;
    private volatile boolean terrainMaterialBrushPreviewValid = false;
    private volatile float terrainMaterialBrushWorldX = 0f;
    private volatile float terrainMaterialBrushWorldY = 0f;
    private volatile float terrainMaterialBrushWorldZ = 0f;
    private volatile float terrainMaterialBrushRadius = 3.0f;
    private volatile int terrainMaterialBrushMaterialIndex = -1;
    // Visual feather width, measured in terrain-cell widths.
    private volatile float terrainMaterialBrushFeather = 2.5f;

    // World/Environment height brush. This edits the currently loaded
    // heightfield in-place; it never regenerates the source heightmap image.
    private volatile boolean heightmapHeightBrushEnabled = false;
    private volatile boolean heightmapHeightBrushRaise = true;
    private volatile boolean heightmapHeightBrushFlatten = false;
    private volatile float heightmapHeightBrushFlattenTarget = 0f;
    private volatile boolean heightmapHeightBrushFlattenTargetValid = false;
    private volatile int heightmapHeightBrushX = -1;
    private volatile int heightmapHeightBrushY = -1;
    private volatile boolean heightmapHeightBrushPaintPending = false;
    private volatile boolean heightmapHeightBrushPreviewValid = false;
    private volatile float heightmapHeightBrushWorldX = 0f;
    private volatile float heightmapHeightBrushWorldY = 0f;
    private volatile float heightmapHeightBrushWorldZ = 0f;
    private volatile float heightmapHeightBrushRadius = 4.0f;
    private volatile float heightmapHeightBrushStrength = 0.75f;
    private final List<HeightmapHeightBrushStroke> heightmapHeightBrushStrokes = new ArrayList<>();


    // Terrain editor undo history. Each brush event stores ONLY the terrain
    // cells changed by that event, rather than replaying the entire brush list.
    // This prevents Ctrl+Z from resetting/reapplying unrelated terrain edits.
    private final java.util.ArrayDeque<TerrainUndoAction> terrainUndoHistory = new java.util.ArrayDeque<>();
    private static final int MAX_TERRAIN_UNDO = 100;
    // OpenGL buffer updates must occur on the GL thread. Ctrl+Z records the
    // localized restore here, and the next display() performs the GPU update.
    private volatile TerrainUndoAction pendingTerrainUndoGpuUpdate = null;

    private static final class TerrainUndoAction {
        final boolean heightAction;
        final int[] indices;
        final float[] previousHeights;
        final float worldX, worldZ, radius;
        final int previousHeightStrokeCount;
        final TerrainBrushStroke materialStroke;

        TerrainUndoAction(int[] indices, float[] previousHeights,
                          float worldX, float worldZ, float radius,
                          int previousHeightStrokeCount) {
            this.heightAction = true;
            this.indices = indices;
            this.previousHeights = previousHeights;
            this.worldX = worldX;
            this.worldZ = worldZ;
            this.radius = radius;
            this.previousHeightStrokeCount = previousHeightStrokeCount;
            this.materialStroke = null;
        }

        TerrainUndoAction(TerrainBrushStroke materialStroke) {
            this.heightAction = false;
            this.indices = null;
            this.previousHeights = null;
            this.worldX = materialStroke == null ? 0f : materialStroke.x;
            this.worldZ = materialStroke == null ? 0f : materialStroke.z;
            this.radius = materialStroke == null ? 0f : materialStroke.radius;
            this.previousHeightStrokeCount = 0;
            this.materialStroke = materialStroke;
        }
    }

    /**
     * Captures only the heightmap cells inside one brush's affected area.
     * The values are copied BEFORE the brush is applied.
     */
    private TerrainUndoAction captureHeightUndoAction(
            float worldX, float worldZ, float radius,
            Heightmaps.HeightmapStageData data) {
        if (data == null || data.heights == null || data.nx < 2 || data.nz < 2) return null;
        radius = Math.max(0.05f, radius);
        float scale = Math.max(0.0001f, data.importScale);
        float terrainWidth = Math.max(0.0001f, data.width * scale);
        float terrainDepth = Math.max(0.0001f, data.depth * scale);
        float halfWidth = terrainWidth * 0.5f;
        float halfDepth = terrainDepth * 0.5f;

        int minX = Math.max(0, (int)Math.floor(((worldX - radius) + halfWidth)
                / terrainWidth * (data.nx - 1)) - 1);
        int maxX = Math.min(data.nx - 1, (int)Math.ceil(((worldX + radius) + halfWidth)
                / terrainWidth * (data.nx - 1)) + 1);
        int minZ = Math.max(0, (int)Math.floor(((worldZ - radius) + halfDepth)
                / terrainDepth * (data.nz - 1)) - 1);
        int maxZ = Math.min(data.nz - 1, (int)Math.ceil(((worldZ + radius) + halfDepth)
                / terrainDepth * (data.nz - 1)) + 1);

        int capacity = Math.max(1, (maxX - minX + 1) * (maxZ - minZ + 1));
        int[] tempIndices = new int[capacity];
        float[] tempHeights = new float[capacity];
        int count = 0;

        for (int z = minZ; z <= maxZ; z++) {
            float wz = (z / (float)(data.nz - 1) - 0.5f) * terrainDepth;
            for (int x = minX; x <= maxX; x++) {
                float wx = (x / (float)(data.nx - 1) - 0.5f) * terrainWidth;
                float dx = wx - worldX;
                float dz = wz - worldZ;
                if (dx * dx + dz * dz > radius * radius) continue;
                int index = z * data.nx + x;
                tempIndices[count] = index;
                tempHeights[count] = data.heights[index];
                count++;
            }
        }

        return new TerrainUndoAction(
                java.util.Arrays.copyOf(tempIndices, count),
                java.util.Arrays.copyOf(tempHeights, count),
                worldX, worldZ, radius, heightmapHeightBrushStrokes.size());
    }

    private void pushTerrainUndoAction(TerrainUndoAction action) {
        if (action == null) return;
        terrainUndoHistory.push(action);
        while (terrainUndoHistory.size() > MAX_TERRAIN_UNDO) terrainUndoHistory.removeLast();
    }

    private void undoTerrainEdit() {
        if (terrainUndoHistory.isEmpty() || currentHeightmapStageData == null) return;
        TerrainUndoAction action = terrainUndoHistory.pop();

        if (action.heightAction) {
            Heightmaps.HeightmapStageData data = currentHeightmapStageData;
            int count = Math.min(action.indices.length, action.previousHeights.length);
            for (int i = 0; i < count; i++) {
                int index = action.indices[i];
                if (index >= 0 && index < data.heights.length) {
                    data.heights[index] = action.previousHeights[i];
                }
            }

            // Remove exactly the height stroke represented by this undo action.
            // Do not touch material strokes or any other height edits.
            while (heightmapHeightBrushStrokes.size() > action.previousHeightStrokeCount) {
                heightmapHeightBrushStrokes.remove(heightmapHeightBrushStrokes.size() - 1);
            }

            // The actual VBO update is deferred to display(), where a valid
            // GL2 context is available. This keeps Ctrl+Z safe from the Swing
            // keyboard event thread while still updating only this brush area.
            pendingTerrainUndoGpuUpdate = action;
        } else {
            // Material painting does not modify height values. Undo only the
            // latest material stroke, leaving every height edit untouched.
            if (!terrainMaterialBrushStrokes.isEmpty()) {
                terrainMaterialBrushStrokes.remove(terrainMaterialBrushStrokes.size() - 1);
            }
        }

        if (gameCanvas != null) gameCanvas.display();
    }

    private static final class HeightmapHeightBrushStroke {
        final float x, z, radius, amount;
        final boolean flatten;
        final float flattenTarget;
        HeightmapHeightBrushStroke(float x, float z, float radius, float amount) {
            this(x, z, radius, amount, false, 0f);
        }
        HeightmapHeightBrushStroke(float x, float z, float radius, float amount, boolean flatten, float flattenTarget) {
            this.x = x;
            this.z = z;
            this.radius = radius;
            this.amount = amount;
            this.flatten = flatten;
            this.flattenTarget = flattenTarget;
        }
    }

    /** Persistent smooth brush decals; these are independent of terrain cell resolution. */
    private static final class TerrainBrushStroke {
        final float x, z, radius;
        final int materialIndex;
        TerrainBrushStroke(float x, float z, float radius, int materialIndex) {
            this.x = x; this.z = z; this.radius = radius; this.materialIndex = materialIndex;
        }
    }
    private final List<TerrainBrushStroke> terrainMaterialBrushStrokes = new ArrayList<>();

