    // ============================================================
    // HEIGHTMAP TERRAIN RUNTIME
    // ============================================================

    // Terrain rendering is chunked so a large imported heightmap never submits
    // its entire index buffer every frame. Shared vertices keep chunk borders
    // continuous while each chunk owns only the indices it needs to draw.
    private static final int HEIGHTMAP_CHUNK_CELLS = 32;
    private static final float HEIGHTMAP_RENDER_DISTANCE = 320.0f;

    private static final class HeightmapTerrainRuntime {
        final Heightmaps.HeightmapStageData data;
        final float[] vertices;
        final ArrayList<HeightmapTerrainChunk> chunks = new ArrayList<>();
        final Texture[] materialTextures;
        final int[] vertexVbo = new int[1];

        HeightmapTerrainRuntime(Heightmaps.HeightmapStageData source) {
            this.data = source;
            int vertexCount = source.nx * source.nz;
            vertices = new float[vertexCount * 8]; // xyz + normal + uv
            float worldWidth = source.width * source.importScale;
            float worldDepth = source.depth * source.importScale;
            float dx = worldWidth / Math.max(1, source.nx - 1);
            float dz = worldDepth / Math.max(1, source.nz - 1);

            for (int z = 0; z < source.nz; z++) {
                for (int x = 0; x < source.nx; x++) {
                    int vi = z * source.nx + x;
                    float vx = (x / (float)(source.nx - 1) - 0.5f) * worldWidth;
                    float vz = (z / (float)(source.nz - 1) - 0.5f) * worldDepth;
                    float h = source.heights[vi] * source.importScale;
                    int xm = Math.max(0, x - 1), xp = Math.min(source.nx - 1, x + 1);
                    int zm = Math.max(0, z - 1), zp = Math.min(source.nz - 1, z + 1);
                    float dhdx = (source.heights[z * source.nx + xp] - source.heights[z * source.nx + xm])
                            * source.importScale / Math.max(0.000001f, (xp - xm) * dx);
                    float dhdz = (source.heights[zp * source.nx + x] - source.heights[zm * source.nx + x])
                            * source.importScale / Math.max(0.000001f, (zp - zm) * dz);
                    float nx = -dhdx, ny = 1f, nz = -dhdz;
                    float len = (float)Math.sqrt(nx * nx + ny * ny + nz * nz);
                    if (len < 0.000001f) len = 1f;
                    int p = vi * 8;
                    vertices[p] = vx; vertices[p + 1] = h; vertices[p + 2] = vz;
                    vertices[p + 3] = nx / len; vertices[p + 4] = ny / len; vertices[p + 5] = nz / len;
                    vertices[p + 6] = x / (float)Math.max(1, source.nx - 1);
                    vertices[p + 7] = 1f - z / (float)Math.max(1, source.nz - 1);
                }
            }

            buildChunks(source, worldWidth, worldDepth);
            materialTextures = new Texture[Math.max(1, source.materials.size())];

        }

        private void buildChunks(Heightmaps.HeightmapStageData source, float worldWidth, float worldDepth) {
            int cellsX = source.nx - 1;
            int cellsZ = source.nz - 1;
            int[] materialIds = source.materialIds == null ? new int[0] : source.materialIds;
            for (int cz = 0; cz < cellsZ; cz += HEIGHTMAP_CHUNK_CELLS) {
                int maxZ = Math.min(cellsZ, cz + HEIGHTMAP_CHUNK_CELLS);
                for (int cx = 0; cx < cellsX; cx += HEIGHTMAP_CHUNK_CELLS) {
                    int maxX = Math.min(cellsX, cx + HEIGHTMAP_CHUNK_CELLS);
                    Map<Integer, ArrayList<Integer>> grouped = new LinkedHashMap<>();
                    for (int z = cz; z < maxZ; z++) {
                        for (int x = cx; x < maxX; x++) {
                            int cell = z * cellsX + x;
                            for (int localTri = 0; localTri < 2; localTri++) {
                                int tri = cell * 2 + localTri;
                                int material = tri < materialIds.length ? Math.max(0, materialIds[tri]) : 0;
                                if (material >= source.materials.size()) material = 0;
                                ArrayList<Integer> list = grouped.computeIfAbsent(material, k -> new ArrayList<>());
                                int a = z * source.nx + x;
                                int b = a + 1;
                                int d = (z + 1) * source.nx + x;
                                int c = d + 1;
                                if (localTri == 0) { list.add(a); list.add(d); list.add(b); }
                                else { list.add(b); list.add(d); list.add(c); }
                            }
                        }
                    }
                    ArrayList<Integer> ordered = new ArrayList<>();
                    ArrayList<MaterialRange> ranges = new ArrayList<>();
                    for (Map.Entry<Integer, ArrayList<Integer>> entry : grouped.entrySet()) {
                        int start = ordered.size();
                        ordered.addAll(entry.getValue());
                        ranges.add(new MaterialRange(entry.getKey(), start, ordered.size() - start));
                    }
                    if (ordered.isEmpty()) continue;
                    int[] indices = new int[ordered.size()];
                    for (int i = 0; i < indices.length; i++) indices[i] = ordered.get(i);
                    float minX = ((float)cx / cellsX - 0.5f) * worldWidth;
                    float maxWorldX = ((float)maxX / cellsX - 0.5f) * worldWidth;
                    float minZ = ((float)cz / cellsZ - 0.5f) * worldDepth;
                    float maxWorldZ = ((float)maxZ / cellsZ - 0.5f) * worldDepth;
                    chunks.add(new HeightmapTerrainChunk(indices, ranges,
                            (minX + maxWorldX) * 0.5f, (minZ + maxWorldZ) * 0.5f,
                            Math.max(Math.abs(maxWorldX - minX), Math.abs(maxWorldZ - minZ)) * 0.75f));
                }
            }
        }

        /**
         * Updates only the vertex data affected by a height brush stroke.
         * The terrain mesh/chunk list is preserved; only changed vertex heights
         * are uploaded instead of rebuilding the complete heightmap runtime.
         */
        void updateHeightRegion(GL2 gl, Heightmaps.HeightmapStageData source, float worldX, float worldZ, float radius) {
            if (source == null || vertexVbo[0] <= 0) return;
            float halfW = source.width * source.importScale * 0.5f;
            float halfD = source.depth * source.importScale * 0.5f;
            int minX = Math.max(0, (int)(((worldX - radius + halfW) / Math.max(0.0001f, source.width * source.importScale)) * (source.nx - 1)));
            int maxX = Math.min(source.nx - 1, (int)(((worldX + radius + halfW) / Math.max(0.0001f, source.width * source.importScale)) * (source.nx - 1)) + 1);
            int minZ = Math.max(0, (int)(((worldZ - radius + halfD) / Math.max(0.0001f, source.depth * source.importScale)) * (source.nz - 1)));
            int maxZ = Math.min(source.nz - 1, (int)(((worldZ + radius + halfD) / Math.max(0.0001f, source.depth * source.importScale)) * (source.nz - 1)) + 1);
            float worldWidth = source.width * source.importScale;
            float worldDepth = source.depth * source.importScale;
            for (int z = minZ; z <= maxZ; z++) {
                for (int x = minX; x <= maxX; x++) {
                    int vi = z * source.nx + x;
                    int p = vi * 8;
                    vertices[p + 1] = source.heights[vi] * source.importScale;
                }
            }
            gl.glBindBuffer(GL2.GL_ARRAY_BUFFER, vertexVbo[0]);
            gl.glBufferSubData(GL2.GL_ARRAY_BUFFER, 0, (long)vertices.length * 4L, FloatBuffer.wrap(vertices));
            gl.glBindBuffer(GL2.GL_ARRAY_BUFFER, 0);
        }

        void upload(GL2 gl) {

            if (chunks.size() > 0 && chunks.get(0).uploaded) return;
            gl.glGenBuffers(1, vertexVbo, 0);
            gl.glBindBuffer(GL2.GL_ARRAY_BUFFER, vertexVbo[0]);
            gl.glBufferData(GL2.GL_ARRAY_BUFFER, (long)vertices.length * 4L, FloatBuffer.wrap(vertices), GL2.GL_STATIC_DRAW);
            for (HeightmapTerrainChunk chunk : chunks) chunk.upload(gl);
            gl.glBindBuffer(GL2.GL_ARRAY_BUFFER, 0);
            gl.glBindBuffer(GL2.GL_ELEMENT_ARRAY_BUFFER, 0);
        }

        void draw(GL2 gl, float cameraX, float cameraZ, int skipMaterialIndex, boolean editMode) {
            if (chunks.isEmpty()) return;
            gl.glEnableClientState(GL2.GL_VERTEX_ARRAY);
            gl.glEnableClientState(GL2.GL_NORMAL_ARRAY);
            gl.glEnableClientState(GL2.GL_TEXTURE_COORD_ARRAY);
            gl.glBindBuffer(GL2.GL_ARRAY_BUFFER, vertexVbo[0]);
            gl.glVertexPointer(3, GL2.GL_FLOAT, 32, 0L);
            gl.glNormalPointer(GL2.GL_FLOAT, 32, 12L);
            gl.glTexCoordPointer(2, GL2.GL_FLOAT, 32, 24L);
            float renderDistanceSq = HEIGHTMAP_RENDER_DISTANCE * HEIGHTMAP_RENDER_DISTANCE;
            for (HeightmapTerrainChunk chunk : chunks) {
                float dx = chunk.centerX - cameraX;
                float dz = chunk.centerZ - cameraZ;
                float allowed = HEIGHTMAP_RENDER_DISTANCE + chunk.radius;
                // Terrain chunk distance culling is a Play Mode optimization.
                // The editor must keep the entire heightmap available so the
                // user can inspect and edit terrain anywhere in the scene.
                if (!editMode &&
                        dx * dx + dz * dz > Math.max(renderDistanceSq, allowed * allowed)) continue;
                gl.glBindBuffer(GL2.GL_ELEMENT_ARRAY_BUFFER, chunk.ebo);
                for (MaterialRange range : chunk.ranges) {
                    // The active brush material is drawn by the soft overlay pass
                    // below. Skipping it here leaves the underlying terrain visible
                    // beneath the feathered alpha edge.
                    if (range.materialIndex == skipMaterialIndex && skipMaterialIndex > 0) continue;
                    Texture texture = range.materialIndex >= 0 && range.materialIndex < materialTextures.length
                            ? materialTextures[range.materialIndex] : null;
                    if (texture != null) { texture.enable(gl); texture.bind(gl); gl.glColor3f(1f,1f,1f); }
                    else { gl.glDisable(GL2.GL_TEXTURE_2D); gl.glColor3f(range.materialIndex == 0 ? 0.48f : 0.55f, range.materialIndex == 0 ? 0.58f : 0.55f, range.materialIndex == 0 ? 0.40f : 0.55f); }
                    gl.glDrawElements(GL2.GL_TRIANGLES, range.count, GL2.GL_UNSIGNED_INT, (long)range.start * 4L);
                    if (texture != null) texture.disable(gl);
                }
            }
            gl.glBindBuffer(GL2.GL_ARRAY_BUFFER, 0);
            gl.glBindBuffer(GL2.GL_ELEMENT_ARRAY_BUFFER, 0);
            gl.glDisableClientState(GL2.GL_TEXTURE_COORD_ARRAY);
            gl.glDisableClientState(GL2.GL_NORMAL_ARRAY);
            gl.glDisableClientState(GL2.GL_VERTEX_ARRAY);
        }

        void dispose(GL2 gl) {
            if (vertexVbo[0] > 0) gl.glDeleteBuffers(1, vertexVbo, 0);
            for (HeightmapTerrainChunk chunk : chunks) chunk.dispose(gl);
            for (Texture texture : materialTextures) if (texture != null) try { texture.destroy(gl); } catch (Throwable ignored) { }
        }
    }

    private static final class HeightmapTerrainChunk {
        final int[] indices;
        final ArrayList<MaterialRange> ranges;
        final float centerX, centerZ, radius;
        int ebo = 0;
        boolean uploaded = false;

        HeightmapTerrainChunk(int[] indices, ArrayList<MaterialRange> ranges,
                              float centerX, float centerZ, float radius) {
            this.indices = indices;
            this.ranges = ranges;
            this.centerX = centerX;
            this.centerZ = centerZ;
            this.radius = radius;
        }

        void upload(GL2 gl) {
            if (uploaded) return;
            int[] id = new int[1];
            gl.glGenBuffers(1, id, 0);
            ebo = id[0];
            gl.glBindBuffer(GL2.GL_ELEMENT_ARRAY_BUFFER, ebo);
            gl.glBufferData(GL2.GL_ELEMENT_ARRAY_BUFFER, (long)indices.length * 4L,
                    IntBuffer.wrap(indices), GL2.GL_STATIC_DRAW);
            gl.glBindBuffer(GL2.GL_ELEMENT_ARRAY_BUFFER, 0);
            uploaded = true;
        }

        void dispose(GL2 gl) {
            if (uploaded && ebo > 0) gl.glDeleteBuffers(1, new int[]{ebo}, 0);
            uploaded = false;
            ebo = 0;
        }
    }

    /**
     * Dedicated water layer. This intentionally has no connection to the
     * heightmap's MaterialRange/materialTextures system. The water surface
     * only uses the explicitly selected normal Material Editor material.
     */
    private static final class WaterTerrainRuntime {
        final Heightmaps.HeightmapStageData data;
        final float[] vertices;
        final int[] indices;
        final int[] vbo = new int[2];
        Texture texture;
        float alpha = 1.0f;
        boolean uploaded = false;

        WaterTerrainRuntime(Heightmaps.HeightmapStageData source) {
            data = source;
            ArrayList<Float> verts = new ArrayList<>();
            ArrayList<Integer> inds = new ArrayList<>();
            int cellsX = Math.max(0, source.nx - 1);
            int cellsZ = Math.max(0, source.nz - 1);
            float worldWidth = source.width * source.importScale;
            float worldDepth = source.depth * source.importScale;
            float waterOffset = source.waterHeight * source.importScale;

            for (int z = 0; z < cellsZ; z++) {
                for (int x = 0; x < cellsX; x++) {
                    int cell = z * cellsX + x;
                    if (!source.waterEnabled || source.waterCells == null
                            || cell >= source.waterCells.length || !source.waterCells[cell]) continue;

                    float x0 = ((float)x / cellsX - 0.5f) * worldWidth;
                    float x1 = ((float)(x + 1) / cellsX - 0.5f) * worldWidth;
                    float z0 = ((float)z / cellsZ - 0.5f) * worldDepth;
                    float z1 = ((float)(z + 1) / cellsZ - 0.5f) * worldDepth;
                    int a = z * source.nx + x;
                    int b = z * source.nx + (x + 1);
                    int c = (z + 1) * source.nx + (x + 1);
                    int d = (z + 1) * source.nx + x;
                    float y = ((source.heights[a] + source.heights[b] + source.heights[c] + source.heights[d]) * 0.25f) * source.importScale + waterOffset;
                    int base = verts.size() / 8;

                    // Water uses world-space UVs, matching how a material would
                    // appear on a normal mapped object instead of restarting
                    // coordinates per generated quad. The water surface is a
                    // terrain-sized layer, so the material should tile smoothly
                    // across the entire selected area while preserving the
                    // original image proportions.
                    float waterTexScale = 0.08f;
                    float u0 = ((x0 / Math.max(1f, worldWidth)) + 0.5f) * waterTexScale;
                    float u1 = ((x1 / Math.max(1f, worldWidth)) + 0.5f) * waterTexScale;
                    float v0 = ((z0 / Math.max(1f, worldDepth)) + 0.5f) * waterTexScale;
                    float v1 = ((z1 / Math.max(1f, worldDepth)) + 0.5f) * waterTexScale;

                    addVertex(verts, x0, y, z0, 0f, 1f, 0f, u0, v0);
                    addVertex(verts, x1, y, z0, 0f, 1f, 0f, u1, v0);
                    addVertex(verts, x1, y, z1, 0f, 1f, 0f, u1, v1);
                    addVertex(verts, x0, y, z1, 0f, 1f, 0f, u0, v1);
                    inds.add(base); inds.add(base + 2); inds.add(base + 1);
                    inds.add(base); inds.add(base + 3); inds.add(base + 2);
                }
            }
            vertices = new float[verts.size()];
            for (int i = 0; i < vertices.length; i++) vertices[i] = verts.get(i);
            indices = new int[inds.size()];
            for (int i = 0; i < indices.length; i++) indices[i] = inds.get(i);
        }

        private static void addVertex(ArrayList<Float> out, float x, float y, float z,
                                      float nx, float ny, float nz, float u, float v) {
            out.add(x); out.add(y); out.add(z);
            out.add(nx); out.add(ny); out.add(nz);
            out.add(u); out.add(v);
        }

        void upload(GL2 gl) {
            if (uploaded || indices.length == 0) return;
            gl.glGenBuffers(2, vbo, 0);
            gl.glBindBuffer(GL2.GL_ARRAY_BUFFER, vbo[0]);
            gl.glBufferData(GL2.GL_ARRAY_BUFFER, (long)vertices.length * 4L,
                    FloatBuffer.wrap(vertices), GL2.GL_STATIC_DRAW);
            gl.glBindBuffer(GL2.GL_ELEMENT_ARRAY_BUFFER, vbo[1]);
            gl.glBufferData(GL2.GL_ELEMENT_ARRAY_BUFFER, (long)indices.length * 4L,
                    IntBuffer.wrap(indices), GL2.GL_STATIC_DRAW);
            gl.glBindBuffer(GL2.GL_ARRAY_BUFFER, 0);
            gl.glBindBuffer(GL2.GL_ELEMENT_ARRAY_BUFFER, 0);
            uploaded = true;
        }

        void dispose(GL2 gl) {
            if (uploaded) gl.glDeleteBuffers(2, vbo, 0);
            if (texture != null) {
                try { texture.destroy(gl); } catch (Throwable ignored) { }
                texture = null;
            }
            uploaded = false;
        }
    }

    private static final class MaterialRange {
        final int materialIndex, start, count;
        MaterialRange(int materialIndex, int start, int count) { this.materialIndex = materialIndex; this.start = start; this.count = count; }
    }

    /** Called by Heightmaps when the user applies a terrain to the current stage. */
    public void applyHeightmapStageData(Heightmaps.HeightmapStageData data) {
        if (data == null || data.nx < 2 || data.nz < 2 || data.heights.length < data.nx * data.nz) return;

        // Reserve material index 0 for the heightmap BASE material. A newly
        // imported heightmap must never inherit whichever brush material was
        // selected in World/Environment Settings.
        ensureHeightmapBaseMaterial(data);

        currentHeightmapStageData = data;
        pendingHeightmapStageData = data;
        heightmapHeightBrushStrokes.clear();
        heightmapHeightBrushEnabled = false;
        heightmapHeightBrushPaintPending = false;
        heightmapHeightBrushFlattenTargetValid = false;
        heightmapHeightBrushPreviewValid = false;
        heightmapHeightBrushX = heightmapHeightBrushY = -1;
        terrainMaterialBrushStrokes.clear();
        // A newly applied heightmap starts a new undo history. Never allow
        // Ctrl+Z to restore cells belonging to a previous terrain.
        terrainUndoHistory.clear();
        pendingTerrainUndoGpuUpdate = null;
        playerX = data.playerX;
        playerZ = data.playerZ;

        // Never leave the player below a newly imported heightmap.
        float importedFloor = data.getHeightAt(playerX, playerZ);
        playerY = Math.max(data.playerY, importedFloor + 0.05f);

        yVelocity = 0f;
        isGrounded = true;
        groundBoundsWidth = Math.max(1f, data.width * data.importScale);
        groundBoundsDepth = Math.max(1f, data.depth * data.importScale);
        if (groundBoundsWidthSpinner != null) groundBoundsWidthSpinner.setValue((double)groundBoundsWidth);
        if (groundBoundsDepthSpinner != null) groundBoundsDepthSpinner.setValue((double)groundBoundsDepth);

        terrainMaterialBrushEnabled = false;
        terrainMaterialBrushMaterialIndex = data.materials.size() > 1 ? 1 : -1;
        terrainMaterialBrushX = terrainMaterialBrushY = -1;
        terrainMaterialBrushPaintPending = false;
        terrainMaterialBrushPreviewValid = false;
        heightmapHeightBrushEnabled = false;
        heightmapHeightBrushPaintPending = false;
        heightmapHeightBrushPreviewValid = false;
        heightmapHeightBrushX = heightmapHeightBrushY = -1;
        if (heightmapHeightBrushButton != null)
            heightmapHeightBrushButton.setText("⛰ Height Brush: OFF");

        playerSpawnPlacementPending = false;
        playerSpawnPlacementCommitPending = false;
        playerSpawnPlacementPreviewValid = false;
        refreshTerrainMaterialBrushControls();
        refreshHeightmapWaterMaterialControls();
        if (heightmapWaterEnabledCheckBox != null) heightmapWaterEnabledCheckBox.setSelected(data.waterEnabled);
        if (heightmapWaterElevationSpinner != null) heightmapWaterElevationSpinner.setValue((double)Math.max(0f, data.waterHeight));
    }

    private void ensureHeightmapBaseMaterial(Heightmaps.HeightmapStageData data) {
        if (data == null || data.materials == null) return;
        if (data.materials.isEmpty()) {
            data.materials.add(new Heightmaps.MaterialBrushMaterial("Heightmap Base", ""));
        }
    }

    private Heightmaps.MaterialBrushMaterial copyMaterialEditorMaterial(
            MaterialEditor.Material material, String fallbackName) {
        Heightmaps.MaterialBrushMaterial result = new Heightmaps.MaterialBrushMaterial();
        if (material == null) {
            result.name = fallbackName == null ? "Terrain Material" : fallbackName;
            return result;
        }
        result.name = material.name == null || material.name.trim().isEmpty()
                ? (fallbackName == null ? "Terrain Material" : fallbackName)
                : material.name.trim();
        result.baseColorMap = material.baseColorMap == null ? "" : material.baseColorMap.trim();
        result.normalMap = material.normalMap == null ? "" : material.normalMap.trim();
        result.metallicMap = material.metallicMap == null ? "" : material.metallicMap.trim();
        result.roughnessMap = material.roughnessMap == null ? "" : material.roughnessMap.trim();
        result.emissionMap = material.emissionMap == null ? "" : material.emissionMap.trim();
        result.metallic = material.metallic;
        result.roughness = material.roughness;
        result.specular = material.specular;
        result.shininess = material.shininess;
        // Preserve Material Editor opacity when available.
        try {
            java.lang.reflect.Field alphaField = material.getClass().getDeclaredField("alpha");
            alphaField.setAccessible(true);
            Object value = alphaField.get(material);
            if (value instanceof Number) result.alpha = Math.max(0f, Math.min(1f, ((Number)value).floatValue()));
        } catch (Throwable ignored) { }
        try {
            java.lang.reflect.Field opacityField = material.getClass().getDeclaredField("opacity");
            opacityField.setAccessible(true);
            Object value = opacityField.get(material);
            if (value instanceof Number) result.alpha = Math.max(0f, Math.min(1f, ((Number)value).floatValue()));
        } catch (Throwable ignored) { }
        return result;
    }

    /**
     * Compares material texture paths without treating equivalent absolute/relative
     * paths as different materials. This is intentionally null/blank safe.
     */
    private static boolean sameMaterialPath(String a, String b) {
        if (a == null || a.trim().isEmpty()) {
            return b == null || b.trim().isEmpty();
        }
        if (b == null || b.trim().isEmpty()) {
            return false;
        }

        String left = a.trim();
        String right = b.trim();
        if (left.equals(right)) {
            return true;
        }

        try {
            File leftFile = new File(left);
            File rightFile = new File(right);
            String leftPath = leftFile.getCanonicalPath();
            String rightPath = rightFile.getCanonicalPath();
            return leftPath.equalsIgnoreCase(rightPath);
        } catch (IOException ignored) {
            // Fall back to normalized absolute paths if canonicalization fails.
            try {
                return new File(left).getAbsolutePath().equalsIgnoreCase(
                        new File(right).getAbsolutePath());
            } catch (Exception ignoredAgain) {
                return left.equalsIgnoreCase(right);
            }
        }
    }

    /** Browse for a .mat and register it in the shared Material Editor recent list. */
    private File browseHeightmapMaterialFile() {
        JFileChooser chooser = new JFileChooser();
        chooser.setDialogTitle("Select Material (.mat)");
        chooser.setFileFilter(new FileNameExtensionFilter("Material files (*.mat)", "mat"));
        chooser.setAcceptAllFileFilterUsed(false);
        if (chooser.showOpenDialog(ctrlFrame) != JFileChooser.APPROVE_OPTION) return null;
        File file = chooser.getSelectedFile();
        if (file == null || !file.isFile()) return null;
        MaterialEditor.Material material = MaterialEditor.loadRecentMaterialFile(file);
        if (material == null) {
            JOptionPane.showMessageDialog(ctrlFrame, "Unable to read the selected .mat material file.",
                    "Material", JOptionPane.ERROR_MESSAGE);
            return null;
        }
        MaterialEditor.rememberRecentMaterialFile(file);
        return file;
    }

    private void browseHeightmapBaseMaterial() {
        File file = browseHeightmapMaterialFile();
        if (file == null) return;
        refreshHeightmapBaseMaterialControls();
        SwingUtilities.invokeLater(() -> {
            for (int i = 0; i < heightmapBaseRecentMaterialFiles.size(); i++) {
                if (sameMaterialPath(heightmapBaseRecentMaterialFiles.get(i).getPath(), file.getPath())) {
                    selectHeightmapBaseMaterial(i + 1);
                    if (heightmapBaseMaterialCombo != null) {
                        refreshingHeightmapBaseMaterialCombo = true;
                        try { heightmapBaseMaterialCombo.setSelectedIndex(i + 1); }
                        finally { refreshingHeightmapBaseMaterialCombo = false; }
                    }
                    return;
                }
            }
        });
    }

    private void browseHeightmapWaterMaterial() {
        File file = browseHeightmapMaterialFile();
        if (file == null) return;
        refreshHeightmapWaterMaterialControls();
        SwingUtilities.invokeLater(() -> {
            for (int i = 0; i < heightmapWaterRecentMaterialFiles.size(); i++) {
                if (sameMaterialPath(heightmapWaterRecentMaterialFiles.get(i).getPath(), file.getPath())) {
                    selectHeightmapWaterMaterial(i + 1);
                    if (heightmapWaterMaterialCombo != null) {
                        refreshingHeightmapWaterMaterialCombo = true;
                        try { heightmapWaterMaterialCombo.setSelectedIndex(i + 1); }
                        finally { refreshingHeightmapWaterMaterialCombo = false; }
                    }
                    return;
                }
            }
        });
    }

    private void browseTerrainBrushMaterial() {
        if (currentHeightmapStageData == null) {
            JOptionPane.showMessageDialog(ctrlFrame,
                    "Apply a heightmap terrain to the current stage before selecting a brush material.",
                    "Terrain Material Brush", JOptionPane.INFORMATION_MESSAGE);
            return;
        }

        File file = browseHeightmapMaterialFile();
        if (file == null) return;
        MaterialEditor.Material material = MaterialEditor.loadRecentMaterialFile(file);
        if (material == null) return;

        Heightmaps.HeightmapStageData data = currentHeightmapStageData;
        ensureHeightmapBaseMaterial(data);
        Heightmaps.MaterialBrushMaterial target = copyMaterialEditorMaterial(material, file.getName());
        int stageIndex = findMatchingTerrainMaterial(data.materials, target);
        if (stageIndex <= 0) {
            data.materials.add(target);
            stageIndex = data.materials.size() - 1;
        }

        terrainMaterialBrushMaterialIndex = stageIndex;
        pendingHeightmapStageData = data;
        final int selectedStageIndex = stageIndex;
        final String selectedName = target.name;

        SwingUtilities.invokeLater(() -> {
            refreshTerrainMaterialBrushControls();
            if (terrainMaterialCombo != null) {
                int comboIndex = -1;
                for (int i = 0; i < terrainRecentMaterialFiles.size(); i++) {
                    if (sameMaterialPath(terrainRecentMaterialFiles.get(i).getPath(), file.getPath())) {
                        comboIndex = i;
                        break;
                    }
                }
                if (comboIndex < 0) {
                    comboIndex = terrainRecentMaterialFiles.size() + Math.max(0, selectedStageIndex - 1);
                }
                if (comboIndex >= 0 && comboIndex < terrainMaterialCombo.getItemCount()) {
                    refreshingTerrainMaterialCombo = true;
                    try { terrainMaterialCombo.setSelectedIndex(comboIndex); }
                    finally { refreshingTerrainMaterialCombo = false; }
                }
            }

            // Explicitly restore the real stage index after the combo refresh.
            terrainMaterialBrushMaterialIndex = selectedStageIndex;
            if (terrainMaterialBrushStatusLabel != null)
                terrainMaterialBrushStatusLabel.setText("Brush material: " + selectedName);

            // Browsing a .mat is itself a brush selection: unlock painting now.
            setTerrainMaterialBrushEnabled(true);
            if (gameCanvas != null) gameCanvas.display();
        });
    }

    private void refreshHeightmapBaseMaterialControls() {
        if (heightmapBaseMaterialCombo == null) return;
        Runnable refresh = () -> {
            refreshingHeightmapBaseMaterialCombo = true;
            try {
                heightmapBaseRecentMaterialFiles.clear();
                heightmapBaseMaterialCombo.removeAllItems();
                heightmapBaseMaterialCombo.addItem("Default Heightmap Material");

                for (File file : MaterialEditor.getRecentMaterialFiles()) {
                    if (file == null || !file.isFile()) continue;
                    MaterialEditor.Material material = MaterialEditor.loadRecentMaterialFile(file);
                    if (material == null) continue;
                    heightmapBaseRecentMaterialFiles.add(file);
                    String name = material.name == null || material.name.trim().isEmpty()
                            ? file.getName() : material.name.trim();
                    heightmapBaseMaterialCombo.addItem(name);
                }

                Heightmaps.HeightmapStageData data = currentHeightmapStageData;
                int selected = 0;
                if (data != null && data.materials != null && !data.materials.isEmpty()) {
                    Heightmaps.MaterialBrushMaterial base = data.materials.get(0);
                    if (base != null) {
                        for (int i = 0; i < heightmapBaseRecentMaterialFiles.size(); i++) {
                            MaterialEditor.Material material =
                                    MaterialEditor.loadRecentMaterialFile(heightmapBaseRecentMaterialFiles.get(i));
                            if (material != null
                                    && sameMaterialPath(base.baseColorMap, material.baseColorMap)
                                    && base.name.equalsIgnoreCase(material.name == null ? "" : material.name.trim())) {
                                selected = i + 1;
                                break;
                            }
                        }
                    }
                }
                heightmapBaseMaterialCombo.setSelectedIndex(
                        Math.max(0, Math.min(selected, heightmapBaseMaterialCombo.getItemCount() - 1)));

                if (heightmapBaseMaterialStatusLabel != null) {
                    heightmapBaseMaterialStatusLabel.setText(
                            "Base material: " + heightmapBaseMaterialCombo.getSelectedItem());
                }
            } finally {
                refreshingHeightmapBaseMaterialCombo = false;
            }
        };
        if (SwingUtilities.isEventDispatchThread()) refresh.run();
        else SwingUtilities.invokeLater(refresh);
    }

    private void selectHeightmapBaseMaterial(int selectedIndex) {
        Heightmaps.HeightmapStageData data = currentHeightmapStageData;
        if (data == null || data.materials == null) return;
        ensureHeightmapBaseMaterial(data);

        if (selectedIndex <= 0) {
            data.materials.set(0, new Heightmaps.MaterialBrushMaterial("Heightmap Base", ""));
        } else {
            int recentIndex = selectedIndex - 1;
            if (recentIndex < 0 || recentIndex >= heightmapBaseRecentMaterialFiles.size()) return;
            File file = heightmapBaseRecentMaterialFiles.get(recentIndex);
            MaterialEditor.Material material = MaterialEditor.loadRecentMaterialFile(file);
            if (material == null) return;
            data.materials.set(0, copyMaterialEditorMaterial(material, file.getName()));
        }

        pendingHeightmapStageData = data;
        if (heightmapBaseMaterialStatusLabel != null)
            heightmapBaseMaterialStatusLabel.setText(
                    "Base material: " + data.materials.get(0).name);
        if (gameCanvas != null) gameCanvas.display();
    }

