    private void refreshTerrainMaterialBrushControls() {
        if (terrainMaterialCombo == null) return;
        Runnable refresh = () -> {
            refreshingTerrainMaterialCombo = true;
            try {
                terrainRecentMaterialFiles.clear();
                terrainMaterialCombo.removeAllItems();

                // Showing recent .mat files does not modify the heightmap.
                // A material is added to the stage only after explicit selection.
                List<File> recent = MaterialEditor.getRecentMaterialFiles();
                for (File file : recent) {
                    if (file == null || !file.isFile()) continue;
                    MaterialEditor.Material material = MaterialEditor.loadRecentMaterialFile(file);
                    if (material == null) continue;
                    terrainRecentMaterialFiles.add(file);
                    String name = material.name == null || material.name.trim().isEmpty()
                            ? file.getName() : material.name.trim();
                    terrainMaterialCombo.addItem(name);
                }

                Heightmaps.HeightmapStageData data = currentHeightmapStageData;
                if (data != null && data.materials != null) {
                    // Material 0 is the BASE material and is never a brush entry.
                    for (int i = 1; i < data.materials.size(); i++) {
                        Heightmaps.MaterialBrushMaterial m = data.materials.get(i);
                        if (m == null) continue;
                        String name = m.name == null || m.name.trim().isEmpty()
                                ? "Terrain Brush Material" : m.name.trim();
                        terrainMaterialCombo.addItem(name);
                    }
                }

                int count = terrainMaterialCombo.getItemCount();
                if (count == 0) {
                    terrainMaterialBrushMaterialIndex = -1;
                    terrainMaterialCombo.setSelectedIndex(-1);
                    terrainMaterialCombo.setEnabled(false);
                    if (terrainMaterialBrushStatusLabel != null)
                        terrainMaterialBrushStatusLabel.setText(
                                "Brush material: none — choose a .mat to paint.");
                } else {
                    terrainMaterialCombo.setEnabled(true);
                    int selected = terrainMaterialCombo.getSelectedIndex();
                    if (selected < 0) selected = 0;
                    terrainMaterialCombo.setSelectedIndex(selected);

                    if (selected < terrainRecentMaterialFiles.size()) {
                        // Crucial: refresh must not call selectRecentTerrainMaterial.
                        terrainMaterialBrushMaterialIndex = -1;
                    } else if (data != null && data.materials != null) {
                        int stageIndex = selected - terrainRecentMaterialFiles.size() + 1;
                        terrainMaterialBrushMaterialIndex =
                                stageIndex < data.materials.size() ? stageIndex : -1;
                    }
                    if (terrainMaterialBrushStatusLabel != null)
                        terrainMaterialBrushStatusLabel.setText(
                                "Brush material: " + terrainMaterialCombo.getItemAt(selected));
                }

                if (terrainMaterialBrushButton != null) {
                    terrainMaterialBrushButton.setText(terrainMaterialBrushEnabled
                            ? "🎨 Painting Terrain" : "🎨 Terrain Material Brush");
                }
            } finally {
                refreshingTerrainMaterialCombo = false;
            }
        };
        if (SwingUtilities.isEventDispatchThread()) refresh.run();
        else SwingUtilities.invokeLater(refresh);
        refreshHeightmapBaseMaterialControls();
    }

    private void selectRecentTerrainMaterial(int selectedIndex) {
        if (selectedIndex < 0 || selectedIndex >= terrainRecentMaterialFiles.size()) return;
        Heightmaps.HeightmapStageData data = currentHeightmapStageData;
        if (data == null || data.materials == null) return;
        ensureHeightmapBaseMaterial(data);

        File file = terrainRecentMaterialFiles.get(selectedIndex);
        MaterialEditor.Material material = MaterialEditor.loadRecentMaterialFile(file);
        if (material == null) return;

        Heightmaps.MaterialBrushMaterial terrainMaterial =
                copyMaterialEditorMaterial(material, file.getName());

        int stageIndex = findMatchingTerrainMaterial(data.materials, terrainMaterial);
        if (stageIndex <= 0) {
            data.materials.add(terrainMaterial);
            stageIndex = data.materials.size() - 1;
        }
        terrainMaterialBrushMaterialIndex = stageIndex;
        pendingHeightmapStageData = data;
        if (!refreshingTerrainMaterialCombo) setTerrainMaterialBrushEnabled(true);

        if (terrainMaterialBrushStatusLabel != null)
            terrainMaterialBrushStatusLabel.setText("Brush material: " + terrainMaterial.name);
    }

    private int findMatchingTerrainMaterial(List<Heightmaps.MaterialBrushMaterial> materials,
                                             Heightmaps.MaterialBrushMaterial target) {
        if (materials == null || target == null) return -1;
        for (int i = 1; i < materials.size(); i++) {
            Heightmaps.MaterialBrushMaterial existing = materials.get(i);
            if (existing == null) continue;
            if (sameMaterialPath(existing.baseColorMap, target.baseColorMap)
                    && sameMaterialPath(existing.normalMap, target.normalMap)
                    && sameMaterialPath(existing.metallicMap, target.metallicMap)
                    && sameMaterialPath(existing.roughnessMap, target.roughnessMap)
                    && sameMaterialPath(existing.emissionMap, target.emissionMap)
                    && existing.name.equals(target.name)) {
                return i;
            }
        }
        return -1;
    }

    private void chooseTerrainMaterialForWorldBrush() {
        if (currentHeightmapStageData == null) {
            JOptionPane.showMessageDialog(ctrlFrame,
                    "Apply a heightmap terrain to the current stage before adding terrain materials.",
                    "Terrain Material Brush", JOptionPane.INFORMATION_MESSAGE);
            return;
        }
        openTerrainMaterialPicker(material -> SwingUtilities.invokeLater(() -> {
            Heightmaps.HeightmapStageData data = currentHeightmapStageData;
            if (data == null || material == null) return;
            ensureHeightmapBaseMaterial(data);

            int existing = findMatchingTerrainMaterial(data.materials, material);
            int newIndex = existing > 0 ? existing : data.materials.size();
            if (existing <= 0) data.materials.add(material);
            terrainMaterialBrushMaterialIndex = newIndex;
            pendingHeightmapStageData = data;
            terrainMaterialBrushEnabled = false;

            refreshTerrainMaterialBrushControls();
            SwingUtilities.invokeLater(() -> {
                if (terrainMaterialCombo != null) {
                    refreshingTerrainMaterialCombo = true;
                    try {
                        int comboIndex = terrainRecentMaterialFiles.size()
                                + Math.max(0, newIndex - 1);
                        if (comboIndex >= 0 && comboIndex < terrainMaterialCombo.getItemCount()) {
                            terrainMaterialCombo.setEnabled(true);
                            terrainMaterialCombo.setSelectedIndex(comboIndex);
                            terrainMaterialBrushMaterialIndex = newIndex;
                        }
                    } finally {
                        refreshingTerrainMaterialCombo = false;
                    }
                    if (terrainMaterialBrushStatusLabel != null)
                        terrainMaterialBrushStatusLabel.setText(
                                "Brush material: " + data.materials.get(newIndex).name);
                }
                if (gameCanvas != null) gameCanvas.repaint();
            });
        }));
    }


    private void updateHeightBrushModeButtons() {
        if (heightmapHeightBrushRaiseButton == null
                || heightmapHeightBrushLowerButton == null
                || heightmapHeightBrushFlattenButton == null) return;

        boolean flatten = heightmapHeightBrushFlatten;
        boolean raise = !flatten && heightmapHeightBrushRaise;
        boolean lower = !flatten && !heightmapHeightBrushRaise;

        heightmapHeightBrushRaiseButton.setText(raise ? "Raise ✓" : "Raise");
        heightmapHeightBrushLowerButton.setText(lower ? "Lower ✓" : "Lower");
        heightmapHeightBrushFlattenButton.setText(flatten ? "Flatten ✓" : "Flatten");

        Font base = heightmapHeightBrushRaiseButton.getFont();
        heightmapHeightBrushRaiseButton.setFont(base.deriveFont(raise ? Font.BOLD : Font.PLAIN));
        heightmapHeightBrushLowerButton.setFont(base.deriveFont(lower ? Font.BOLD : Font.PLAIN));
        heightmapHeightBrushFlattenButton.setFont(base.deriveFont(flatten ? Font.BOLD : Font.PLAIN));
    }

    private void setHeightmapHeightBrushEnabled(boolean enabled) {
        heightmapHeightBrushEnabled = enabled && isEditMode() && currentHeightmapStageData != null;
        if (heightmapHeightBrushEnabled) {
            // The two terrain editing tools share the left mouse button.
            // Never let both consume the same click.
            setTerrainMaterialBrushEnabled(false);
        }
        heightmapHeightBrushX = heightmapHeightBrushY = -1;
        heightmapHeightBrushPaintPending = false;
        heightmapHeightBrushPreviewValid = false;
        if (heightmapHeightBrushButton != null) {
            heightmapHeightBrushButton.setText(heightmapHeightBrushEnabled
                    ? "⛰ Height Brush: ON" : "⛰ Height Brush: OFF");
        }
        updateHeightBrushModeButtons();
        if (heightmapHeightBrushStatusLabel != null && heightmapHeightBrushEnabled)
            heightmapHeightBrushStatusLabel.setText(
                    heightmapHeightBrushFlatten ? "Mode: Flatten"
                    : (heightmapHeightBrushRaise ? "Mode: Raise" : "Mode: Lower"));
        if (gameCanvas != null) {
            gameCanvas.setCursor(heightmapHeightBrushEnabled
                    ? Cursor.getPredefinedCursor(Cursor.CROSSHAIR_CURSOR)
                    : Cursor.getDefaultCursor());
            gameCanvas.display();
        }
    }

