    private static final String TPG_PROJECT_VERSION = "2";

    // Internal blank-project environment.  A blank project deliberately keeps
    // the same simple visual baseline used by the editor: an untextured white
    // ground and a calm teal sky when no custom skybox is assigned.
    private static final float BLANK_SKY_R = 0.10f;
    private static final float BLANK_SKY_G = 0.55f;
    private static final float BLANK_SKY_B = 0.62f;
    private volatile boolean internalBlankProjectActive = true;
    private volatile long activeProjectGeneration = 0L;

    private File ensureInternalBlankProjectFile() throws IOException {
        File root = new File(System.getProperty("java.io.tmpdir"), "WorldsGLProjects");
        if (!root.isDirectory() && !root.mkdirs()) {
            throw new IOException("Could not create internal WorldsGL project directory.");
        }
        File blank = new File(root, "blank.tpgproject");
        Properties manifest = new Properties();
        manifest.setProperty("project.format", "WorldsGL Third Person Game Project");
        manifest.setProperty("project.version", TPG_PROJECT_VERSION);
        manifest.setProperty("ground.texture", "");
        manifest.setProperty("sky.front", "");
        manifest.setProperty("sky.back", "");
        manifest.setProperty("sky.left", "");
        manifest.setProperty("sky.right", "");
        manifest.setProperty("sky.top", "");
        manifest.setProperty("sky.bottom", "");
        manifest.setProperty("objects.count", "0");
        manifest.setProperty("timeline.scenes.count", "0");
        try (ZipOutputStream zip = new ZipOutputStream(new BufferedOutputStream(new FileOutputStream(blank)))) {
            zip.putNextEntry(new ZipEntry("project.properties"));
            ByteArrayOutputStream bytes = new ByteArrayOutputStream();
            try (OutputStream propOut = bytes) {
                manifest.store(propOut, "WorldsGL internal blank project");
            }
            zip.write(bytes.toByteArray());
            zip.closeEntry();
        }
        return blank;
    }

    private void activateInternalBlankProject() {
        internalBlankProjectActive = true;
        try {
            File blank = ensureInternalBlankProjectFile();
            readProjectFile(blank);
        } catch (Exception ex) {
            // Keep the direct reset as a safe fallback if the internal archive
            // cannot be created/read. The renderer still gets the same blank
            // white-ground/teal-sky environment below.
            System.err.println("Could not load internal blank.tpgproject: " + ex.getMessage());
            clearProjectToDefaults();
        }
        activeProjectGeneration++;
        internalBlankProjectActive = true;
        currentProjectPath = null;
        groundTexturePath = null;
        skyFrontPath = skyBackPath = skyLeftPath = null;
        skyRightPath = skyTopPath = skyBottomPath = null;
        pendingGroundPath = null;
        pendingSkyFrontPath = pendingSkyBackPath = pendingSkyLeftPath = null;
        pendingSkyRightPath = pendingSkyTopPath = pendingSkyBottomPath = null;
        pendingProjectReset = true;
        objectInspectorRuntimeResetPending = true;
        selectedObjectIndex = -1;
    }

