            r.givesHP = Boolean.parseBoolean(manifest.getProperty(k + "givesHP", "false"));
            r.hpAmount = Math.max(0, projectInt(manifest, k + "hpAmount", 10));
            r.attacksPlayer = Boolean.parseBoolean(manifest.getProperty(k + "attacksPlayer", "false"));
            r.attackDamage = Math.max(0, projectInt(manifest, k + "attackDamage", 10));
            r.questItem = Boolean.parseBoolean(manifest.getProperty(k + "questItem", "false"));
            r.questName = manifest.getProperty(k + "questName", "");
            r.inventoryItem = Boolean.parseBoolean(manifest.getProperty(k + "inventoryItem", "false"));
            r.inventoryItemId = manifest.getProperty(k + "inventoryItemId", "");
            r.inventoryItemName = manifest.getProperty(k + "inventoryItemName", "");
