    private void refreshEnvironmentRenderingControls() {
        SwingUtilities.invokeLater(() -> {
            if (objectShadowsCheckBox != null) objectShadowsCheckBox.setSelected(objectShadowsEnabled);
            if (sceneFogCheckBox != null) sceneFogCheckBox.setSelected(sceneFogEnabled);
            if (sceneFogLevelCombo != null) {
                sceneFogLevelCombo.setSelectedIndex(Math.max(0, Math.min(3, sceneFogLevel)));
                sceneFogLevelCombo.setEnabled(sceneFogEnabled);
            }
            if(showPlayerInventoryCheckBox!=null)showPlayerInventoryCheckBox.setSelected(showPlayerInventory);
            if(playerInventoryCapacitySpinner!=null)playerInventoryCapacitySpinner.setValue(Math.max(1,Math.min(60,playerInventoryCapacity)));
            if(playerInventoryPositionCombo!=null)playerInventoryPositionCombo.setSelectedIndex(Math.max(0,Math.min(1,playerInventoryPosition)));
        });
    }

    private String getProjectSettingsWindowTitle() {
        String projectName = "Untitled.tpgproject";
        if (currentProjectPath != null && !currentProjectPath.trim().isEmpty()) {
            try {
                String name = new File(currentProjectPath).getName();
                if (!name.trim().isEmpty()) projectName = name;
            } catch (Exception ignored) { }
        }
        return "World/Environment Settings";
    }

    private void updateProjectSettingsWindowTitle() {
        if (ctrlFrame != null) ctrlFrame.setTitle(getProjectSettingsWindowTitle());
    }

    private void applyEditorLayoutTheme() {
        if (ctrlFrame != null) applyEditorThemeToComponent(ctrlFrame.getContentPane(), darkLayoutEnabled);
        if (objectInspectorFrame != null) applyEditorThemeToComponent(objectInspectorFrame.getContentPane(), darkLayoutEnabled);
        if (darkLayoutToggle != null) {
            darkLayoutToggle.setText(darkLayoutEnabled ? "Disable Dark Layout" : "Enable Dark Layout");
            darkLayoutToggle.setSelected(darkLayoutEnabled);
        }
        if (ctrlFrame != null) { ctrlFrame.revalidate(); ctrlFrame.repaint(); }
        if (objectInspectorFrame != null) { objectInspectorFrame.revalidate(); objectInspectorFrame.repaint(); }
    }

    /**
     * Applies the editor theme directly to the actual Swing input components.
     * In particular, JSpinner/JComboBox editors are composite components, so
     * changing only the outer control leaves their embedded JTextField white.
     */
    private void applyEditorThemeToComponent(Component component, boolean dark) {
        if (component == null) return;

        Color panelBg = dark ? new Color(48, 48, 52) : UIManager.getColor("Panel.background");
        Color inputBg = dark ? Color.DARK_GRAY : UIManager.getColor("TextField.background");
        Color fg = dark ? Color.WHITE : UIManager.getColor("Label.foreground");
        if (panelBg == null) panelBg = dark ? new Color(48, 48, 52) : Color.WHITE;
        if (inputBg == null) inputBg = dark ? Color.DARK_GRAY : Color.WHITE;
        if (fg == null) fg = dark ? Color.WHITE : Color.BLACK;

        if (component instanceof JPanel || component instanceof JViewport || component instanceof JScrollPane
                || component instanceof JTabbedPane || component instanceof JRootPane || component instanceof JMenuBar) {
            ((JComponent) component).setBackground(panelBg);
        }

        if (component instanceof JComponent) {
            JComponent jc = (JComponent) component;
            if (jc.getBorder() instanceof javax.swing.border.TitledBorder) {
                javax.swing.border.TitledBorder titled =
                        (javax.swing.border.TitledBorder) jc.getBorder();
                titled.setTitleColor(fg);
            }
        }

        if (component instanceof JMenuBar) {
            JMenuBar bar = (JMenuBar) component;
            bar.setOpaque(true);
            bar.setBackground(dark ? new Color(62, 62, 68) : UIManager.getColor("Menu.background"));
        }

        if (component instanceof JMenu || component instanceof JMenuItem) {
            component.setBackground(dark ? new Color(62, 62, 68) : UIManager.getColor("Menu.background"));
            component.setForeground(fg);
            if (component instanceof JComponent) ((JComponent) component).setOpaque(true);
        }

        if (component instanceof JLabel || component instanceof JCheckBox || component instanceof JToggleButton
                || component instanceof JButton || component instanceof JList || component instanceof JTabbedPane) {
            component.setForeground(fg);
        }

        if (component instanceof AbstractButton) {
            component.setBackground(dark ? new Color(62, 62, 68) : UIManager.getColor("Button.background"));
            ((AbstractButton) component).setOpaque(dark);
        }

        if (component instanceof JCheckBox) {
            ((JCheckBox) component).setBackground(panelBg);
            ((JCheckBox) component).setOpaque(false);
        }

        // Every normal JTextField gets its actual paint surface changed.
        // This is intentionally separate from the generic component foreground
        // handling so white LAF defaults cannot remain visible in dark mode.
        if (component instanceof JTextField) {
            JTextField textField = (JTextField) component;
            textField.setOpaque(true);
            textField.setBackground(inputBg);
            textField.setForeground(fg);
            textField.setCaretColor(fg);
            textField.setSelectionColor(dark ? new Color(90, 90, 90) : UIManager.getColor("TextField.selectionBackground"));
            textField.setSelectedTextColor(fg);
            textField.setDisabledTextColor(dark ? new Color(170, 170, 170) : UIManager.getColor("TextField.disabledForeground"));
        }

        // Formatted fields are also JTextFields, but explicitly style them for
        // Look & Feel implementations that repaint their editor background.
        if (component instanceof JFormattedTextField) {
            JFormattedTextField textField = (JFormattedTextField) component;
            textField.setOpaque(true);
            textField.setBackground(inputBg);
            textField.setForeground(fg);
            textField.setCaretColor(fg);
            textField.setSelectedTextColor(fg);
            textField.setSelectionColor(dark ? new Color(90, 90, 90) : UIManager.getColor("TextField.selectionBackground"));
        }

        if (component instanceof JSpinner) {
            JSpinner spinner = (JSpinner) component;

            // IMPORTANT: many Swing Look & Feels do not use the spinner's
            // own background/foreground for the visible number. The number
            // is painted by a JTextComponent inside the spinner editor.
            // Style that editor directly and deliberately use BLACK as the
            // editor background with WHITE text in dark layout mode. The
            // editor UI delegate itself is normalized so these are the
            // actual paint colors. No spinner borders are modified.
            Color spinnerBg = dark ? Color.BLACK : UIManager.getColor("TextField.background");
            Color spinnerFg = dark ? Color.WHITE : UIManager.getColor("TextField.foreground");
            if (spinnerBg == null) spinnerBg = Color.BLACK;
            if (spinnerFg == null) spinnerFg = Color.WHITE;

            spinner.setOpaque(true);
            spinner.setBackground(spinnerBg);
            spinner.setForeground(spinnerFg);

            // Keep every JSpinner at one predictable editor size.  The
            // embedded text-editor UI must never be allowed to shrink the
            // spinner when dark mode changes the Look & Feel delegate.
            spinner.setPreferredSize(new Dimension(90, 24));
            spinner.setMinimumSize(new Dimension(90, 24));

            JComponent editor = spinner.getEditor();
            if (editor != null) {
                editor.setOpaque(true);
                editor.setBackground(spinnerBg);
                editor.setForeground(spinnerFg);
                forceSpinnerEditorColors(editor, spinnerFg, spinnerBg);
            }


            spinner.revalidate();
            spinner.repaint();

            // Some Windows/Nimbus delegates repaint their editor immediately
            // after the component hierarchy is invalidated. Re-apply the
            // colors once on the EDT after that repaint cycle as well.
            if (dark) {
                SwingUtilities.invokeLater(() -> {
                    JComponent delayedEditor = spinner.getEditor();
                    if (delayedEditor != null) {
                        forceSpinnerEditorColors(delayedEditor, Color.WHITE, Color.BLACK);
                    }
                    spinner.setForeground(Color.WHITE);
                    spinner.setBackground(Color.BLACK);
                    spinner.repaint();
                });
            }
        }

        if (component instanceof JComboBox) {
            JComboBox<?> combo = (JComboBox<?>) component;
            combo.setOpaque(true);
            combo.setBackground(inputBg);
            combo.setForeground(fg);
            if (combo.isEditable()) {
                Component editor = combo.getEditor().getEditorComponent();
                if (editor != null) applyInputSurface(editor, fg, inputBg, dark);
            }
        }

        if (component instanceof JList) {
            component.setBackground(dark ? new Color(42, 42, 46) : UIManager.getColor("List.background"));
            component.setForeground(fg);
        }

        if (component instanceof JScrollPane) {
            JScrollPane sp = (JScrollPane) component;
            sp.setOpaque(true);
            sp.setBackground(panelBg);
            sp.getViewport().setBackground(panelBg);
            sp.getVerticalScrollBar().setBackground(panelBg);
            sp.getHorizontalScrollBar().setBackground(panelBg);
        }

        if (component instanceof JMenuBar) {
            JMenuBar bar = (JMenuBar) component;
            Color menuBg = dark ? new Color(62, 62, 68) : UIManager.getColor("Menu.background");
            bar.setBackground(menuBg);
            bar.setForeground(fg);
        }
        if (component instanceof JMenu) {
            JMenu menu = (JMenu) component;
            menu.setOpaque(true);
            menu.setBackground(dark ? new Color(62, 62, 68) : UIManager.getColor("Menu.background"));
            menu.setForeground(fg);
            menu.getPopupMenu().setBackground(dark ? new Color(62, 62, 68) : UIManager.getColor("Menu.background"));
            menu.getPopupMenu().setForeground(fg);
        }
        if (component instanceof JMenuItem) {
            JMenuItem item = (JMenuItem) component;
            item.setOpaque(true);
            item.setBackground(dark ? new Color(62, 62, 68) : UIManager.getColor("MenuItem.background"));
            item.setForeground(fg);
        }

        if (component instanceof Container) {
            for (Component child : ((Container) component).getComponents()) {
                applyEditorThemeToComponent(child, dark);
            }
        }

        // IMPORTANT: recurse first, then restore the spinner editor colors.
        // The recursive pass also sees the editor's JTextField and the normal
        // text-field branch would otherwise overwrite the spinner-specific
        // colors. This final pass guarantees the actual numeric text field is
        // BLACK with WHITE text in dark layout mode.
        if (component instanceof JSpinner && dark) {
            JSpinner spinner = (JSpinner) component;
            forceSpinnerEditorColors(spinner.getEditor(), Color.WHITE, Color.BLACK);
            spinner.setForeground(Color.WHITE);
            spinner.setBackground(Color.BLACK);
            spinner.revalidate();
            spinner.repaint();
        }
    }

    /**
     * Forces the real text component used by a JSpinner editor to the supplied
     * colors. This deliberately handles JTextComponent rather than only
     * JTextField because JSpinner.NumberEditor uses JFormattedTextField.
     */
    private static void forceSpinnerEditorColors(Component component, Color foreground, Color background) {
        if (component == null) return;

        if (component instanceof JFormattedTextField) {
            JFormattedTextField text = (JFormattedTextField) component;

            // JSpinner.NumberEditor uses JFormattedTextField. Some Look & Feel
            // delegates repaint that editor using their own TextField colors,
            // which can ignore setBackground(). Use Swing's basic formatted
            // text-field UI for the editor itself so the component's own
            // background/foreground are the actual paint colors.
            if (!(text.getUI() instanceof javax.swing.plaf.basic.BasicFormattedTextFieldUI)) {
                text.setUI(new javax.swing.plaf.basic.BasicFormattedTextFieldUI());
            }

            text.setOpaque(true);
            text.setForeground(foreground);
            text.setBackground(background);
            text.setCaretColor(foreground);
            text.setSelectedTextColor(background);
            text.setSelectionColor(foreground);
        } else if (component instanceof JTextField) {
            JTextField text = (JTextField) component;

            // Apply the basic text-field UI only to the spinner's embedded
            // text editor. No borders are changed here.
            if (!(text.getUI() instanceof javax.swing.plaf.basic.BasicTextFieldUI)) {
                text.setUI(new javax.swing.plaf.basic.BasicTextFieldUI());
            }

            text.setOpaque(true);
            text.setForeground(foreground);
            text.setBackground(background);
            text.setCaretColor(foreground);
            text.setSelectedTextColor(background);
            text.setSelectionColor(foreground);
        } else if (component instanceof javax.swing.text.JTextComponent) {
            javax.swing.text.JTextComponent text =
                    (javax.swing.text.JTextComponent) component;
            text.setOpaque(true);
            text.setForeground(foreground);
            text.setBackground(background);
            text.setCaretColor(foreground);
            text.setSelectedTextColor(background);
            text.setSelectionColor(foreground);
        } else if (component instanceof JComponent) {
            JComponent jc = (JComponent) component;
            jc.setOpaque(true);
            jc.setForeground(foreground);
            jc.setBackground(background);
        }

        if (component instanceof JSpinner) {
            JSpinner spinner = (JSpinner) component;
            spinner.setPreferredSize(new Dimension(90, 24));
            spinner.setMinimumSize(new Dimension(90, 24));
        }

        if (component instanceof Container) {
            for (Component child : ((Container) component).getComponents()) {
                forceSpinnerEditorColors(child, foreground, background);
            }
        }
    }

    /** Directly styles an input/editor child, including nested spinner fields. */
    private static void applyInputSurface(Component component, Color foreground, Color background, boolean dark) {
        if (component == null) return;
        if (component instanceof JTextField) {
            JTextField field = (JTextField) component;
            field.setOpaque(true);
            field.setBackground(background);
            field.setForeground(foreground);
            field.setCaretColor(foreground);
            field.setSelectedTextColor(foreground);
            field.setSelectionColor(dark ? new Color(90, 90, 90) : UIManager.getColor("TextField.selectionBackground"));
        } else if (component instanceof JComponent) {
            JComponent jc = (JComponent) component;
            jc.setBackground(background);
            jc.setForeground(foreground);
            if (!(component instanceof JButton)) jc.setOpaque(true);
        }
        if (component instanceof Container) {
            for (Component child : ((Container) component).getComponents()) {
                applyInputSurface(child, foreground, background, dark);
            }
        }
    }

    private void createObjectInspectorFrame() {
        if (objectInspectorFrame != null) objectInspectorFrame.dispose();
        objectInspectorFrame = new JFrame("Object Inspector");
        objectInspectorFrame.setDefaultCloseOperation(JFrame.HIDE_ON_CLOSE);
        objectInspectorFrame.setResizable(true);

        objectInspectorListModel = new DefaultListModel<>();
        objectInspectorList = new JList<>(objectInspectorListModel);
        objectInspectorList.setSelectionMode(ListSelectionModel.MULTIPLE_INTERVAL_SELECTION);
        objectInspectorList.setFont(objectInspectorList.getFont().deriveFont(Font.PLAIN, 13f));
        objectInspectorList.setCellRenderer(new DefaultListCellRenderer() {
            @Override public Component getListCellRendererComponent(JList<?> list, Object value, int index, boolean selected, boolean focus) {
                JLabel label = (JLabel) super.getListCellRendererComponent(list, value, index, selected, focus);
                if (value instanceof ObjectInspectorEntry) {
                    ObjectInspectorEntry e = (ObjectInspectorEntry)value;
                    boolean hidden = e.player ? playerHidden : (e.sceneTrigger
                            ? isInspectorSceneTriggerHidden(e.selectableIndex)
                            : (e.object != null && e.object.hidden));
                    String icon = e.player ? "🎮" : (e.sceneTrigger ? "🎬" : (e.object != null && e.object.isEmptyItem ? "💎" : (e.object != null && e.object.isBlock ? "■" : (e.object != null && e.object.isParticle ? "✨" : (e.object != null && e.object.isBGMMusic ? "♫" : (e.object != null && e.object.isLightSource ? "💡" : "⛄"))))));
                    label.setText(icon + " " + e.name);
                    if (hidden) label.setFont(label.getFont().deriveFont(Font.ITALIC));
                    Color normal = darkLayoutEnabled ? Color.WHITE : list.getForeground();
                    Color selectedColor = darkLayoutEnabled ? Color.WHITE : list.getSelectionForeground();
                    Color hiddenColor = darkLayoutEnabled ? Color.LIGHT_GRAY : Color.GRAY;
                    Color normalBg = darkLayoutEnabled ? new Color(42, 42, 46) : list.getBackground();
                    Color selectedBg = darkLayoutEnabled ? new Color(82, 82, 90) : list.getSelectionBackground();
                    // Hidden objects retain the familiar grey text in both
                    // light and dark layouts. Selection still controls the
                    // background so hidden selected objects remain visible.
                    label.setForeground(hidden ? hiddenColor : (selected ? selectedColor : normal));
                    label.setBackground(selected ? selectedBg : normalBg);
                    label.setOpaque(true);
                }
                label.setBorder(BorderFactory.createEmptyBorder(6, 7, 6, 7));
                return label;
            }
        });
        objectInspectorList.addListSelectionListener(e -> {
            // Left mouse selection is committed by our mouse handler below. This
            // listener remains responsible for keyboard navigation and any other
            // selection changes, but must never fight an in-progress mouse gesture.
            if (refreshingObjectInspector || e.getValueIsAdjusting()
                    || inspectorMouseSelectionInProgress
                    || inspectorApplyingMouseSelection
                    || inspectorSelectionProcessingQueued) return;
            inspectorSelectionProcessingQueued = true;
            SwingUtilities.invokeLater(() -> {
                inspectorSelectionProcessingQueued = false;
                if (refreshingObjectInspector || objectInspectorList == null
                        || inspectorMouseSelectionInProgress
                        || inspectorApplyingMouseSelection) return;
                processInspectorSelectionFromList(-1);
            });
        });
        objectInspectorList.addMouseListener(new MouseAdapter() {
            @Override public void mousePressed(MouseEvent e) {
                if (!e.isPopupTrigger() && e.getButton() == MouseEvent.BUTTON1) {
                    int row = objectInspectorList.locationToIndex(e.getPoint());
                    Rectangle bounds = row >= 0 ? objectInspectorList.getCellBounds(row, row) : null;
                    int clickedRow = (row >= 0 && bounds != null && bounds.contains(e.getPoint())) ? row : -1;
                    if (clickedRow >= 0) {
                        // Take a snapshot BEFORE BasicListUI can change anything.
                        inspectorMouseSelectionRow = clickedRow;
                        inspectorMouseSelectionBeforeClick = objectInspectorList.getSelectedIndices();
                        int anchor = objectInspectorList.getSelectionModel().getAnchorSelectionIndex();
                        inspectorMouseSelectionAnchorRow = (anchor >= 0
                                && anchor < objectInspectorList.getModel().getSize())
                                ? anchor : clickedRow;
                        inspectorMouseSelectionInProgress = true;

                        // Consume the gesture so Swing's BasicListUI does not
                        // perform an intermediate selection. We apply the complete
                        // selection exactly once on mouse release.
                        e.consume();
                    } else {
                        inspectorMouseSelectionRow = -1;
                        inspectorMouseSelectionInProgress = false;
                    }
                }
                handleObjectInspectorMouse(e);
            }

            @Override public void mouseReleased(MouseEvent e) {
                if (e.isPopupTrigger()) {
                    inspectorMouseSelectionInProgress = false;
                    handleObjectInspectorMouse(e);
                    return;
                }

                if (e.getButton() == MouseEvent.BUTTON1 && inspectorMouseSelectionInProgress) {
                    final int clickedRow = inspectorMouseSelectionRow;
                    final boolean shift = e.isShiftDown();
                    final boolean ctrl = e.isControlDown();
                    final int anchorRow = inspectorMouseSelectionAnchorRow;
                    final int[] before = inspectorMouseSelectionBeforeClick;

                    inspectorMouseSelectionInProgress = false;
                    inspectorApplyingMouseSelection = true;
                    try {
                        if (clickedRow >= 0 && clickedRow < objectInspectorList.getModel().getSize()) {
                            LinkedHashSet<Integer> finalRows = new LinkedHashSet<>();

                            if (shift) {
                                int anchor = anchorRow >= 0 ? anchorRow : clickedRow;
                                int from = Math.min(anchor, clickedRow);
                                int to = Math.max(anchor, clickedRow);
                                if (ctrl) {
                                    for (int row : before) finalRows.add(row);
                                }
                                for (int row = from; row <= to; row++) finalRows.add(row);
                            } else if (ctrl) {
                                for (int row : before) finalRows.add(row);
                                if (finalRows.contains(clickedRow)) finalRows.remove(clickedRow);
                                else finalRows.add(clickedRow);
                                inspectorMouseSelectionAnchorRow = clickedRow;
                            } else {
                                finalRows.add(clickedRow);
                                inspectorMouseSelectionAnchorRow = clickedRow;
                            }

                            int[] indices = finalRows.stream().mapToInt(Integer::intValue).toArray();
                            objectInspectorList.setSelectedIndices(indices);
                            objectInspectorList.ensureIndexIsVisible(clickedRow);

                            // Now that the JList has its final, stable selection,
                            // synchronize the engine once and only once.
                            processInspectorSelectionFromList(clickedRow);
                        }
                    } finally {
                        inspectorApplyingMouseSelection = false;
                    }
                    e.consume();
                }
            }
        });
        objectInspectorList.getInputMap(JComponent.WHEN_FOCUSED).put(KeyStroke.getKeyStroke("F2"), "renameObject");
        objectInspectorList.getActionMap().put("renameObject", new AbstractAction() { public void actionPerformed(java.awt.event.ActionEvent e) { renameInspectorSelection(); } });

        JPanel root = new JPanel(new BorderLayout(6, 6));
        root.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));

        // Top-level File menu: project/file and editor actions formerly exposed
        // as large buttons in World/Project/Environment Settings.
        JMenuBar inspectorMenuBar = new JMenuBar();
        JMenu fileMenu = new JMenu("File");

        JMenuItem newProjectItem = new JMenuItem("New .tpgproject");
        newProjectItem.addActionListener(e -> {
            int answer = JOptionPane.showConfirmDialog(
                    objectInspectorFrame,
                    "Create a new project? The current scene will be cleared.",
                    "New WorldsGL Project",
                    JOptionPane.YES_NO_OPTION,
                    JOptionPane.WARNING_MESSAGE);
            if (answer == JOptionPane.YES_OPTION) {
                activateInternalBlankProject();
                updateProjectSettingsWindowTitle();
                refreshSelectedObjectSelector();
                refreshProjectileObjectCombo();
            }
        });
        JMenuItem openProjectItem = new JMenuItem("Open .tpgproject");
        openProjectItem.addActionListener(e -> loadProjectDialog(objectInspectorFrame));
        JMenuItem saveProjectItem = new JMenuItem("Save .tpgproject");
        saveProjectItem.addActionListener(e -> saveProjectDialog(objectInspectorFrame));
        JMenuItem exportJarItem = new JMenuItem("Export to .JAR");
        exportJarItem.addActionListener(e -> exportProjectToJarDialog(objectInspectorFrame));
        JMenuItem exportMultiplayerJarItem = new JMenuItem("Export to .JAR with multiplayer/servers");
        exportMultiplayerJarItem.addActionListener(e -> exportProjectToJarDialog(objectInspectorFrame, true));
        JMenuItem materialEditorItem = new JMenuItem("Open Material Editor");
        materialEditorItem.addActionListener(e -> openMaterialEditor());
        JMenuItem animationsEditorItem = new JMenuItem("Open Animations Editor");
        animationsEditorItem.addActionListener(e -> {
            try {
                File projectContext = null;
                if (currentProjectPath != null && !currentProjectPath.trim().isEmpty()) {
                    File candidate = new File(currentProjectPath);
                    if (candidate.isFile()) projectContext = candidate;
                }
                AnimationsEditor editor = new AnimationsEditor(
                        null, projectContext, this::refreshAttachedWGAnimProfileFromProject);
                editor.setVisible(true);
            } catch (Throwable ex) {
                JOptionPane.showMessageDialog(objectInspectorFrame,
                        "Could not open Animations Editor:\n" + ex.getMessage(),
                        "Animations Editor", JOptionPane.ERROR_MESSAGE);
            }
        });
        JMenuItem audioManagerItem = new JMenuItem("Open Audio Manager");
        audioManagerItem.addActionListener(e -> openAudioManager(objectInspectorFrame));
        JMenuItem timelineEditorItem = new JMenuItem("Open Timeline Editor");
        timelineEditorItem.addActionListener(e -> openTimelineEditor(objectInspectorFrame));
        JMenuItem openSceneItem = new JMenuItem("Open Scene");
        openSceneItem.addActionListener(e -> openSceneChooser(objectInspectorFrame));
        JMenuItem saveSceneItem = new JMenuItem("Save Scene");
        saveSceneItem.addActionListener(e -> saveCurrentScene(objectInspectorFrame));
        JMenuItem exitItem = new JMenuItem("Exit");
        exitItem.addActionListener(e -> System.exit(0));

        fileMenu.add(newProjectItem);
        fileMenu.add(openProjectItem);
        fileMenu.add(saveProjectItem);
        fileMenu.addSeparator();
        fileMenu.add(exportJarItem);
        fileMenu.add(exportMultiplayerJarItem);
        fileMenu.addSeparator();
        fileMenu.add(materialEditorItem);
        fileMenu.add(animationsEditorItem);
        fileMenu.add(audioManagerItem);
        fileMenu.add(timelineEditorItem);
        fileMenu.addSeparator();
        fileMenu.add(openSceneItem);
        fileMenu.add(saveSceneItem);
        fileMenu.addSeparator();
        fileMenu.add(exitItem);
        inspectorMenuBar.add(fileMenu);

        JLabel title = new JLabel("Scene Objects");
        title.setFont(title.getFont().deriveFont(Font.BOLD, 14f));
        JPanel inspectorHeader = new JPanel(new BorderLayout(4, 2));
        inspectorHeader.setOpaque(true);
        inspectorHeader.setOpaque(true);
        inspectorHeader.setBackground(darkLayoutEnabled ? new Color(48, 48, 52) : UIManager.getColor("Panel.background"));
        inspectorMenuBar.setOpaque(true);
        inspectorMenuBar.setBackground(darkLayoutEnabled ? new Color(62, 62, 68) : UIManager.getColor("Menu.background"));
        inspectorMenuBar.setBorder(BorderFactory.createEmptyBorder(1, 1, 1, 1));
        fileMenu.setOpaque(true);
        fileMenu.setBackground(darkLayoutEnabled ? new Color(62, 62, 68) : UIManager.getColor("Menu.background"));
        fileMenu.setForeground(darkLayoutEnabled ? Color.WHITE : UIManager.getColor("Menu.foreground"));
        fileMenu.getPopupMenu().setOpaque(true);
        fileMenu.getPopupMenu().setBackground(darkLayoutEnabled ? new Color(62, 62, 68) : UIManager.getColor("Menu.background"));
        inspectorHeader.add(inspectorMenuBar, BorderLayout.NORTH);
        inspectorHeader.add(title, BorderLayout.SOUTH);
        root.add(inspectorHeader, BorderLayout.NORTH);
        JScrollPane scroll = new JScrollPane(objectInspectorList);
        scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        // The creation menu must also work when the inspector has no objects
        // (or when the user right-clicks below the last row).  Forward popup
        // triggers from the scroll pane and its viewport to the same handler.
        MouseAdapter inspectorBlankSpacePopup = new MouseAdapter() {
            @Override public void mousePressed(MouseEvent e) {
                if (e.isPopupTrigger()) createObjectInspectorCreateMenu().show(e.getComponent(), e.getX(), e.getY());
            }
            @Override public void mouseReleased(MouseEvent e) {
                if (e.isPopupTrigger()) createObjectInspectorCreateMenu().show(e.getComponent(), e.getX(), e.getY());
            }
        };
        scroll.getViewport().addMouseListener(inspectorBlankSpacePopup);
        scroll.addMouseListener(inspectorBlankSpacePopup);
        root.add(scroll, BorderLayout.CENTER);
        JLabel hint = new JLabel("Double-click / F2 to rename  •  Right-click for options");
        hint.setBorder(BorderFactory.createEmptyBorder(4, 2, 2, 2));
        root.add(hint, BorderLayout.SOUTH);
        objectInspectorFrame.setContentPane(root);
        objectInspectorFrame.setSize(280, 900);
        positionEditorWindows();
        objectInspectorFrame.setVisible(true);
        refreshObjectInspector();
        applyEditorLayoutTheme();
    }

    private void positionEditorWindows() {
        if (ctrlFrame == null) return;
        Rectangle screen = GraphicsEnvironment.getLocalGraphicsEnvironment().getMaximumWindowBounds();
        // Keep the three editor regions proportional on smaller monitors so
        // the right-side settings never get clipped while the 3D viewport
        // remains large enough to be genuinely usable.
        double fit = Math.min(1.0, screen.width / 1460.0);
        int inspectorW = Math.max(215, (int)Math.round(245 * fit));
        int settingsW = Math.max(360, (int)Math.round(380 * fit));
        int gameW = Math.max(500, screen.width - inspectorW - settingsW);
        if (inspectorW + settingsW + gameW > screen.width) {
            gameW = Math.max(460, screen.width - inspectorW - settingsW);
        }
        int height = Math.min(620, screen.height);
        if (objectInspectorFrame != null) { objectInspectorFrame.setBounds(screen.x, screen.y, inspectorW, height); }
        ctrlFrame.setBounds(screen.x + inspectorW + gameW, screen.y, settingsW, height);
        Window gameWindow = null;
        for (Window w : Window.getWindows()) if (w instanceof JFrame && ((JFrame)w).getTitle() != null && ((JFrame)w).getTitle().startsWith("3D Third Person Game")) { gameWindow = w; break; }
        if (gameWindow != null) gameWindow.setBounds(screen.x + inspectorW, screen.y, gameW, height);
    }

    private JPopupMenu createObjectInspectorCreateMenu() {
        JPopupMenu menu = new JPopupMenu();
        JMenu create = new JMenu("Create New Object");

        JMenuItem createOBJ = new JMenuItem("⛄ New .OBJ Object");
        createOBJ.addActionListener(a -> queueInspectorOBJCreation());
        create.add(createOBJ);

        JMenuItem createBlock = new JMenuItem("■ New Block");
        createBlock.setToolTipText("Creates a simple model-less 1×1×1 solid block.");
        createBlock.addActionListener(a -> queueInspectorBlockCreation());
        create.add(createBlock);

        JMenuItem createEmptyItem = new JMenuItem("💎 New Item");
        createEmptyItem.setToolTipText(
                "Creates a model-less item object that can be classified and used by the inventory/Behavior Tree system.");
        createEmptyItem.addActionListener(a -> queueInspectorEmptyItemCreation());
        create.add(createEmptyItem);

        JMenuItem createLight = new JMenuItem("💡 New Light Source");
        createLight.addActionListener(a -> queueInspectorLightCreation());
        create.add(createLight);

        JMenuItem createBGM = new JMenuItem("♫ New BGMMusic");
        createBGM.addActionListener(a -> queueInspectorBGMMusicCreation());
        create.add(createBGM);

        JMenuItem createParticle = new JMenuItem("✨ New Particle");
        createParticle.addActionListener(a -> queueInspectorParticleCreation());
        create.add(createParticle);

        JMenuItem createTrigger = new JMenuItem("🎬 New Scene Trigger");
        createTrigger.addActionListener(a -> createSceneTriggerFromInspector());
        create.add(createTrigger);

        menu.add(create);
        return menu;
    }

    /**
     * Opens the Player's inspector Properties window. The Player is not a
     * SpawnedObject, so it gets its own properties entry point. This is
     * intentionally established now so player model/texture/material and
     * animation editing can be expanded here without making the Player
     * deletable.
     */
