        GridBagConstraints gbc = new GridBagConstraints();
        gbc.insets = new Insets(4, 4, 4, 4);
        gbc.fill = GridBagConstraints.HORIZONTAL;
        gbc.weightx = 1.0;

        // Keep the Player's asset display identical to normal Object Properties:
        // friendly object-based names are shown while the real paths remain in tooltips.
        String playerObjectName = "Player";
        addObjectPropertyDisplayField(generalContent, gbc, 0, "OBJ:",
                playerModelPath == null || playerModelPath.trim().isEmpty()
                        ? "None" : playerObjectName + ".obj",
                playerModelPath);

        // The player does not currently have a separate project material entry,
        // so expose a friendly material name now while using the player's texture
        // as the base-color source for the same Material Editor preview renderer.
        addObjectPropertyDisplayField(generalContent, gbc, 1, "Material:",
                "Player Material", "Player material");

        String playerTextureExtension = getObjectPropertyImageExtension(playerTexturePath);
        addObjectPropertyDisplayField(generalContent, gbc, 2, "Texture:",
                playerTexturePath == null || playerTexturePath.trim().isEmpty()
                        ? "None" : playerObjectName + playerTextureExtension,
                playerTexturePath);

        JLabel speedLabel = new JLabel("Player Speed:");
        JSpinner speedSpinner = new JSpinner(new SpinnerNumberModel(
                (double) Math.max(0.001f, Math.min(2.0f, playerMoveSpeed)),
                0.001, 2.0, 0.01));
        speedSpinner.setToolTipText(
                "Controls how quickly the player moves forward/backward. Higher values are faster.");
        speedSpinner.addChangeListener(e -> {
            playerMoveSpeed = Math.max(0.001f, ((Number) speedSpinner.getValue()).floatValue());
        });
        GridBagConstraints speedLabelGbc = (GridBagConstraints) gbc.clone();
        speedLabelGbc.gridx = 0; speedLabelGbc.gridy = 3; speedLabelGbc.weightx = 0.0; speedLabelGbc.fill = GridBagConstraints.NONE;
        generalContent.add(speedLabel, speedLabelGbc);
