    private String getObjectPropertyImageExtension(String path) {
        if (path == null || path.trim().isEmpty()) return ".jpg";
        String name = new File(path.trim()).getName();
        int dot = name.lastIndexOf('.');
        if (dot >= 0 && dot < name.length() - 1) {
            String ext = name.substring(dot).toLowerCase(Locale.ROOT);
            if (ext.equals(".png") || ext.equals(".jpg") || ext.equals(".jpeg")
                    || ext.equals(".bmp") || ext.equals(".gif") || ext.equals(".tga")) {
                return ext;
            }
        }
        return ".jpg";
    }

    /**
     * Returns a compact display name for Object Properties without changing
     * the underlying asset path. Only the filename is shown, and very long
     * filenames are shortened in the middle so their extension and ending
     * remain visible. The complete path is retained by the field tooltip.
     */
    private String compactObjectPropertyFilename(String path) {
        String fileName;
        try {
            fileName = new File(path).getName();
        } catch (Throwable ignored) {
            fileName = path;
        }

        if (fileName == null || fileName.isEmpty()) {
            fileName = path;
        }

        final int maxCharacters = 48;
        if (fileName.length() <= maxCharacters) {
            return fileName;
        }

        String extension = "";
        int dot = fileName.lastIndexOf('.');
        if (dot > 0 && dot < fileName.length() - 1) {
            extension = fileName.substring(dot);
        }

        int available = maxCharacters - extension.length() - 1;
        if (available < 10) {
            return fileName.substring(0, maxCharacters - 1) + "\u2026";
        }

        int prefixLength = available / 2;
        int suffixLength = available - prefixLength;
        return fileName.substring(0, prefixLength)
                + "\u2026"
                + fileName.substring(fileName.length() - suffixLength);
    }

    private void processInspectorSelectionFromList(int clickedRow) {
        if (objectInspectorList == null || refreshingObjectInspector) return;

        // For mouse clicks, use the exact row captured from the mouse event.
        // This is more reliable than getSelectedIndex() or even the lead row
        // because Swing can briefly retain the previous lead during a Shift/Ctrl
        // selection event. For keyboard navigation, fall back to the lead row.
        ListSelectionModel selectionModel = objectInspectorList.getSelectionModel();
        int primaryRow = clickedRow >= 0 ? clickedRow : selectionModel.getLeadSelectionIndex();
        if (primaryRow < 0 || primaryRow >= objectInspectorList.getModel().getSize()) return;

        ObjectInspectorEntry entry = objectInspectorList.getModel().getElementAt(primaryRow);
        if (entry == null) return;
        if (entry.player || entry.sceneTrigger) {
            inspectorMultiSelection.clear();
            selectObjectFromInspector(entry.player ? -1 : entry.selectableIndex);
        } else {
            syncInspectorMultiSelectionFromList(primaryRow);
            selectObjectFromInspector(entry.selectableIndex);
        }
    }

    private void syncInspectorMultiSelectionFromList(int primaryRow) {
        if (objectInspectorList == null) return;
        int[] rows = objectInspectorList.getSelectedIndices();
        inspectorMultiSelection.clear();
        for (int row : rows) {
            if (row < 0 || row >= objectInspectorList.getModel().getSize()) continue;
            ObjectInspectorEntry entry = objectInspectorList.getModel().getElementAt(row);
            if (entry != null && !entry.player && !entry.sceneTrigger && entry.object != null) {
                inspectorMultiSelection.add(entry.object);
            }
        }
        // Keep the clicked object as the canonical/primary selection.
        if (primaryRow >= 0 && primaryRow < objectInspectorList.getModel().getSize()) {
            ObjectInspectorEntry entry = objectInspectorList.getModel().getElementAt(primaryRow);
            if (entry != null && entry.object != null) {
                selectedObjectIndex = spawnedObjects.indexOf(entry.object);
                playerSelectedInInspector = false;
            }
        }
    }

    private List<SpawnedObject> getInspectorTransformSelection() {
        ArrayList<SpawnedObject> result = new ArrayList<>();
        for (SpawnedObject object : inspectorMultiSelection) {
            if (object != null && spawnedObjects.contains(object)) result.add(object);
        }
        if (result.isEmpty()) {
            SpawnedObject selected = getSelectedObject();
            if (selected != null) result.add(selected);
        }
        return result;
    }

    private void showMoveSelectedObjectsDialog() {
        List<SpawnedObject> selected = getInspectorTransformSelection();
        if (selected.size() < 2) return;

        JPanel panel = new JPanel(new GridLayout(3, 2, 5, 5));
        JSpinner dx = new JSpinner(new SpinnerNumberModel(0.0, -100000.0, 100000.0, 0.1));
        JSpinner dy = new JSpinner(new SpinnerNumberModel(0.0, -100000.0, 100000.0, 0.1));
        JSpinner dz = new JSpinner(new SpinnerNumberModel(0.0, -100000.0, 100000.0, 0.1));
        panel.add(new JLabel("Move X by:")); panel.add(dx);
        panel.add(new JLabel("Move Y by:")); panel.add(dy);
        panel.add(new JLabel("Move Z by:")); panel.add(dz);

        int answer = JOptionPane.showConfirmDialog(
                objectInspectorFrame, panel,
                "Move " + selected.size() + " Selected Objects Together",
                JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE);
        if (answer != JOptionPane.OK_OPTION) return;

        float moveX = ((Number) dx.getValue()).floatValue();
        float moveY = ((Number) dy.getValue()).floatValue();
        float moveZ = ((Number) dz.getValue()).floatValue();
        for (SpawnedObject object : selected) {
            object.x += moveX;
            object.y += moveY;
            object.z += moveZ;
        }
        refreshObjectInspector();
        if (gameCanvas != null) gameCanvas.display();
    }

    private void handleObjectInspectorMouse(MouseEvent e) {
        // Never intercept normal left-click selection. Swing's native JList
        // selection model must receive the event so MULTIPLE_INTERVAL_SELECTION
        // can select any number of objects with Shift-click/Ctrl-click.
        if (!e.isPopupTrigger() && e.getButton() == MouseEvent.BUTTON1) {
            if (e.getClickCount() == 2 && !e.isShiftDown() && !e.isControlDown()) {
                SwingUtilities.invokeLater(() -> {
                    if (objectInspectorList != null && objectInspectorList.getSelectedValue() != null) {
                        renameInspectorSelection();
                    }
                });
            }
            return;
        }

        if (!e.isPopupTrigger() && e.getButton() != MouseEvent.BUTTON3) return;
        int row = objectInspectorList.locationToIndex(e.getPoint());
        Rectangle bounds = row >= 0 ? objectInspectorList.getCellBounds(row, row) : null;
        if (row < 0 || bounds == null || !bounds.contains(e.getPoint())) {
            // Allow creation from empty/white inspector space as well as from
            // an existing object row.
            createObjectInspectorCreateMenu().show(
                    objectInspectorList, e.getX(), e.getY());
            return;
        }
        ObjectInspectorEntry entry = objectInspectorList.getModel().getElementAt(row);
        if (entry == null) return;
        if (!objectInspectorList.isSelectedIndex(row)) {
            objectInspectorList.setSelectedIndex(row);
            inspectorMultiSelection.clear();
            if (entry.object != null) inspectorMultiSelection.add(entry.object);
        }
        selectObjectFromInspector(entry.selectableIndex);

        JPopupMenu menu = createObjectInspectorCreateMenu();
        menu.addSeparator();

        if (!entry.sceneTrigger && !entry.player) {
            if (inspectorMultiSelection.size() > 1) {
                JMenuItem moveSelected = new JMenuItem(
                        "Move Selected Together (" + inspectorMultiSelection.size() + ")");
                moveSelected.addActionListener(a -> showMoveSelectedObjectsDialog());
                menu.add(moveSelected);
                menu.addSeparator();
            }

            JMenuItem rename = new JMenuItem("Rename");
            rename.addActionListener(a -> renameInspectorSelection());
            menu.add(rename);

            JMenuItem duplicate = new JMenuItem("Duplicate");
            duplicate.addActionListener(a -> {
                pendingObjectActionTarget = entry.object;
                duplicateSelectedObjectRequested = true;
            });
            menu.add(duplicate);

            JMenuItem delete = new JMenuItem("Delete");
            delete.addActionListener(a -> {
                if (confirmDeleteObject(entry.object)) {
                    pendingObjectActionTarget = entry.object;
                    deleteSelectedObjectRequested = true;
                }
            });
            menu.add(delete);

            JMenuItem hide = new JMenuItem(entry.object != null && entry.object.hidden ? "Show" : "Hide");
            hide.addActionListener(a -> {
                if (entry.object != null) {
                    entry.object.hidden = !entry.object.hidden;
                    refreshObjectInspector();
                }
            });
            menu.add(hide);

                JMenuItem objectProperties = new JMenuItem("Properties");
            objectProperties.addActionListener(a -> showObjectProperties(entry.object));
            objectProperties.setEnabled(entry.object != null);
            menu.add(objectProperties);

            JMenu attach = new JMenu("Attach to Behavior Tree");
            JMenuItem none = new JMenuItem("None");
            none.addActionListener(a -> assignInspectorBehaviorTree(BehaviorTree.NONE));
            attach.add(none);
            for (String name : behaviorTreeProfiles.keySet()) {
                final String treeName = name;
                JMenuItem item = new JMenuItem(treeName);
                item.addActionListener(a -> assignInspectorBehaviorTree(treeName));
                attach.add(item);
            }
            menu.add(attach);
        } else if (entry.player) {
            // The Player is protected from deletion, but it remains a fully
            // accessible inspector object. Its Properties window is kept
            // separate from SpawnedObject properties so it can later expose
            // the player's model, texture, material, and animation settings.
            JMenuItem playerProperties = new JMenuItem("Properties");
            playerProperties.addActionListener(a -> showPlayerProperties());
            menu.add(playerProperties);

            JMenuItem delete = new JMenuItem("Delete");
            delete.setEnabled(false);
            delete.setToolTipText("The Player is required and cannot be deleted.");
            menu.add(delete);
        } else {
            // Scene triggers are virtual inspector objects rather than
            // SpawnedObject instances. Their destination belongs to the
            // individual trigger, so it is edited directly from this menu.
            JMenuItem hideTrigger = new JMenuItem("Hide");
            int visibilityIndex = getSelectedSceneTriggerIndex();
            if (visibilityIndex >= 0 && visibilityIndex < sceneTriggers.size()
                    && sceneTriggers.get(visibilityIndex).hidden) {
                hideTrigger.setText("Show");
            }
            hideTrigger.addActionListener(a -> {
                int ti = getSelectedSceneTriggerIndex();
                if (ti >= 0 && ti < sceneTriggers.size()) {
                    sceneTriggers.get(ti).hidden = !sceneTriggers.get(ti).hidden;
                    syncCurrentTimelineScene();
                    refreshObjectInspector();
                }
            });
            menu.add(hideTrigger);

            JMenu destination = new JMenu("Destination Scene");
            int triggerIndex = getSelectedSceneTriggerIndex();
            SceneTrigger trigger = triggerIndex >= 0 && triggerIndex < sceneTriggers.size()
                    ? sceneTriggers.get(triggerIndex) : null;
            if (trigger != null && timelineScenes.isEmpty()) {
                JMenuItem noneScene = new JMenuItem("No scenes available");
                noneScene.setEnabled(false);
                destination.add(noneScene);
            } else if (trigger != null) {
                for (int i = 0; i < timelineScenes.size(); i++) {
                    final int sceneIndex = i;
                    String sceneName = timelineScenes.get(i).getProperty(
                            "scene.name", "Scene " + i);
                    JMenuItem item = new JMenuItem(i + ": " + sceneName);
                    item.setFont(item.getFont().deriveFont(
                            i == trigger.destinationScene ? Font.BOLD : Font.PLAIN));
                    item.addActionListener(a -> {
                        trigger.destinationScene = sceneIndex;
                        syncCurrentTimelineScene();
                        refreshSceneTriggerDestinationsRequested = true;
                        refreshObjectInspector();
                    });
                    destination.add(item);
                }
            } else {
                JMenuItem unavailable = new JMenuItem("Trigger unavailable");
                unavailable.setEnabled(false);
                destination.add(unavailable);
            }
            menu.add(destination);

            JMenuItem deleteTrigger = new JMenuItem("Delete Scene Trigger");
            deleteTrigger.addActionListener(a -> deleteSelectedSceneTriggerFromInspector());
            menu.add(deleteTrigger);
        }

        menu.show(objectInspectorList, bounds.x + 8, bounds.y + bounds.height);
    }

    private void queueInspectorOBJCreation() {
        String path = chooseOBJFile();
        if (path == null || path.trim().isEmpty()) return;
        synchronized (pendingObjectSpawnRequests) {
            String selectedBehavior = behaviorProfileCombo == null
                    ? "" : (String) behaviorProfileCombo.getSelectedItem();
            String selectedAction = actionProfileCombo == null
                    ? ActionBuilder.NONE : (String) actionProfileCombo.getSelectedItem();
            String selectedTree = behaviorTreeProfileCombo == null
                    ? "" : (String) behaviorTreeProfileCombo.getSelectedItem();

            SpawnRequest request = new SpawnRequest(
                    path, false, false, false, false, false, "");
            request.behaviorProfileName = selectedBehavior == null
                    || "Select a behavior...".equals(selectedBehavior) ? "" : selectedBehavior.trim();
            applyBehaviorProfileToRequest(request);
            request.behaviorTreeProfileName = selectedTree == null
                    || BehaviorTree.NONE.equals(selectedTree) ? "" : selectedTree.trim();
            request.actionProfileName = selectedAction == null
                    || ActionBuilder.NONE.equals(selectedAction) ? ActionBuilder.NONE : selectedAction.trim();
            applyActionProfileToRequest(request);
            request.objectName = deriveObjectName(path);
            request.x = Float.NaN;
            pendingObjectSpawnRequests.add(request);
        }
    }

    private void queueInspectorBlockCreation() {
        synchronized (pendingObjectSpawnRequests) {
            SpawnRequest request = new SpawnRequest("", false, false, false, false, false, "");
            request.isBlock = true;
            request.objectName = "Block";
            request.collision = true;
            request.physics = false;

            // Blocks are normal scene objects, so inherit the same optional
            // behavior/action/tree assignment mechanism used by OBJ objects.
            String selectedBehavior = behaviorProfileCombo == null
                    ? "" : (String) behaviorProfileCombo.getSelectedItem();
            String selectedAction = actionProfileCombo == null
                    ? ActionBuilder.NONE : (String) actionProfileCombo.getSelectedItem();
            String selectedTree = behaviorTreeProfileCombo == null
                    ? "" : (String) behaviorTreeProfileCombo.getSelectedItem();
            request.behaviorProfileName = selectedBehavior == null
                    || "Select a behavior...".equals(selectedBehavior) ? "" : selectedBehavior.trim();
            request.actionProfileName = selectedAction == null
                    || ActionBuilder.NONE.equals(selectedAction) ? ActionBuilder.NONE : selectedAction.trim();
            request.behaviorTreeProfileName = selectedTree == null
                    || BehaviorTree.NONE.equals(selectedTree) ? "" : selectedTree.trim();
            applyBehaviorProfileToRequest(request);
            applyActionProfileToRequest(request);

            // Spawn the block immediately beside the player rather than relying on
            // the generic model spawn fallback.  Give it a deliberately visible
            // size and place its base on the same Y level as the player.
            float forwardRadians = (float) Math.toRadians(playerRot);
            float blockDistance = 3.0f;
            // Deliberately large enough to be unmistakable in the stage.
            request.scale = 2.0f;
            request.x = playerX + (float) Math.sin(forwardRadians) * blockDistance;
            request.y = playerY;
            request.z = playerZ + (float) Math.cos(forwardRadians) * blockDistance;
            request.rotationX = 0.0f;
            request.rotationY = 0.0f;
            request.rotationZ = 0.0f;
            pendingObjectSpawnRequests.add(request);
        }
    }

    private void queueInspectorEmptyItemCreation() {
        String name = JOptionPane.showInputDialog(
                objectInspectorFrame,
                "Name for the new empty item object:",
                "New Empty Item Object",
                JOptionPane.PLAIN_MESSAGE);

        if (name == null) return;
        name = name.trim();
        if (name.isEmpty()) {
            JOptionPane.showMessageDialog(
                    objectInspectorFrame,
                    "Please enter a name for the item object.",
                    "New Empty Item Object",
                    JOptionPane.WARNING_MESSAGE);
            return;
        }

        synchronized (pendingObjectSpawnRequests) {
            SpawnRequest request = new SpawnRequest(
                    "", false, false, false, false, false, "");
            request.isEmptyItem = true;
            request.objectName = name;
            request.inventoryItem = true;
            // This is an explicit item-object name supplied by the user, not an
            // inferred asset filename, so it is safe to use as the initial item ID
            // and display name. Both remain editable from Object Properties.
            request.inventoryItemId = name;
            request.inventoryItemName = name;
            request.inventoryItemQuantity = 1;
            request.inventoryItemMaxStack = 99;
            request.inventoryItemUseObjAsIcon = false;
            request.inventoryItemCustomIconPath = "";
            request.x = Float.NaN;
            pendingObjectSpawnRequests.add(request);
        }
    }

    private void queueInspectorLightCreation() {
        synchronized (pendingObjectSpawnRequests) {
            SpawnRequest request = new SpawnRequest(
                    "", false, false, false, false, false, "");
            request.objectName = "Light Source";
            request.x = Float.NaN;
            request.lightRadius = 6.0f;
            request.lightIntensity = 1.0f;
            request.lightColorR = 1.0f;
            request.lightColorG = 1.0f;
            request.lightColorB = 1.0f;
            pendingObjectSpawnRequests.add(request);
        }
    }

    private String findDefaultParticleTexture() {
        List<File> candidates = new ArrayList<>();
        candidates.add(new File("particle.png"));
        if (currentProjectPath != null && !currentProjectPath.trim().isEmpty()) {
            File project = new File(currentProjectPath);
            File parent = project.getParentFile();
            if (parent != null) candidates.add(new File(parent, "particle.png"));
        }
        try {
            File code = new File(ThirdPersonGameNew.class.getProtectionDomain().getCodeSource().getLocation().toURI());
            File base = code.isFile() ? code.getParentFile() : code;
            if (base != null) candidates.add(new File(base, "particle.png"));
        } catch (Exception ignored) { }
        for (File candidate : candidates) {
            if (candidate != null && candidate.isFile()) return candidate.getAbsolutePath();
        }
        return null;
    }

    private void queueInspectorParticleCreation() {
        String texturePath = findDefaultParticleTexture();
        if (texturePath == null || texturePath.trim().isEmpty()) texturePath = chooseTextureFile();
        if (texturePath == null || texturePath.trim().isEmpty()) return;
        synchronized (pendingObjectSpawnRequests) {
            SpawnRequest request = new SpawnRequest("", false, false, false, false, false, "");
            request.objectName = "Particle";
            request.isParticle = true;
            request.texturePath = texturePath;
            request.x = Float.NaN;
            pendingObjectSpawnRequests.add(request);
        }
    }

    private void queueInspectorBGMMusicCreation() {
        synchronized (pendingObjectSpawnRequests) {
            SpawnRequest request = new SpawnRequest("", false, false, false, false, false, "");
            request.objectName = "Background Music";
            request.isBGMMusic = true;
            request.audioLoop = true;
            request.audioPlayOnSceneStart = true;
            request.audioVolume = 1.0f;
            request.x = playerX; request.y = playerY; request.z = playerZ;
            pendingObjectSpawnRequests.add(request);
        }
    }

    private void createSceneTriggerFromInspector() {
        SceneTrigger trigger = new SceneTrigger();
        // Place newly-created triggers a short distance in front of the player
        // so creation cannot immediately intersect the player and transition
        // to another scene. The game uses +Z/+sin(playerRot) as forward.
        float forwardDistance = 3.0f;
        double forwardRadians = Math.toRadians(playerRot);
        trigger.x = playerX + (float) Math.sin(forwardRadians) * forwardDistance;
        trigger.y = playerY;
        trigger.z = playerZ + (float) Math.cos(forwardRadians) * forwardDistance;
        trigger.width = 2.0f;
        trigger.height = 2.5f;
        trigger.depth = 0.5f;
        trigger.rotationY = 0.0f;
        trigger.enabled = true;
        trigger.creationGraceFrames = 45;
        trigger.destinationScene = timelineScenes.size() > 1
                ? (currentSceneIndex + 1 < timelineScenes.size() ? currentSceneIndex + 1 : 0)
                : currentSceneIndex;
        sceneTriggers.add(trigger);
        selectedObjectIndex = spawnedObjects.size() + sceneTriggers.size() - 1;
        refreshSelectedObjectSelector();
        refreshSceneTriggerDestinationsRequested = true;
    }

    private void deleteSelectedSceneTriggerFromInspector() {
        int index = getSelectedSceneTriggerIndex();
        if (index < 0 || index >= sceneTriggers.size()) return;
        sceneTriggers.remove(index);
        selectedObjectIndex = sceneTriggers.isEmpty()
                ? -1
                : spawnedObjects.size() + Math.min(index, sceneTriggers.size() - 1);
        refreshSelectedObjectSelector();
        refreshProjectileObjectCombo();
        refreshSceneTriggerDestinationsRequested = true;
    }

    private boolean confirmDeleteObject(SpawnedObject object) {
        if (object == null) return false;
        int result = JOptionPane.showConfirmDialog(objectInspectorFrame, "Delete \"" + getObjectDisplayName(object, selectedObjectIndex) + "\"?", "Delete Object", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
        return result == JOptionPane.YES_OPTION;
    }

    private void renameInspectorSelection() {
        if (playerSelectedInInspector) return;
        SpawnedObject object = getSelectedObject();
        if (object == null) return;
        String current = getObjectDisplayName(object, selectedObjectIndex);
        String value = JOptionPane.showInputDialog(objectInspectorFrame, "Object name:", current);
        if (value == null) return;
        value = value.trim();
        if (value.isEmpty()) return;
        object.objectName = ensureUniqueObjectName(value, object);
        refreshSelectedObjectSelector();
        refreshProjectileObjectCombo();
    }

    private void assignInspectorBehaviorTree(String name) {
        SpawnedObject object = getSelectedObject();
        if (object == null || object.isLightSource) return;
        object.behaviorTreeProfileName = BehaviorTree.NONE.equals(name) ? "" : name;
        refreshBehaviorTreeProfileCombo();
        refreshObjectInspector();
    }

