        hudPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
        hudPanel.add(playerHealthBarCheckBox);
        hudPanel.add(enemyHealthBarsCheckBox);
        hudPanel.add(scoreCheckBox);

        // Keep Show player inventory directly underneath Show Points in the same
        // HUD checkbox stack. It is intentionally NOT placed inside the
        // Player Inventory titled panel.
        showPlayerInventoryCheckBox=new JCheckBox("Show Player Inventory",showPlayerInventory);
        showPlayerInventoryCheckBox.setAlignmentX(Component.LEFT_ALIGNMENT);
        showPlayerInventoryCheckBox.setHorizontalAlignment(SwingConstants.LEFT);
        showPlayerInventoryCheckBox.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 0));
        showPlayerInventoryCheckBox.setMargin(new Insets(0, 0, 0, 0));
        showPlayerInventoryCheckBox.addActionListener(e->showPlayerInventory=showPlayerInventoryCheckBox.isSelected());
        hudPanel.add(showPlayerInventoryCheckBox);
        addControlComponent(ctrlContent, hudPanel);

        JPanel inventoryHudPanel=new JPanel();
        inventoryHudPanel.setLayout(new BoxLayout(inventoryHudPanel,BoxLayout.Y_AXIS)); inventoryHudPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
        inventoryHudPanel.setBorder(BorderFactory.createTitledBorder("Player Inventory"));
        JPanel capacityRow=new JPanel(new FlowLayout(FlowLayout.LEFT,4,2)); capacityRow.add(new JLabel("Inventory spaces:"));
        playerInventoryCapacitySpinner=new JSpinner(new SpinnerNumberModel(Math.max(1,Math.min(60,playerInventoryCapacity)),1,60,1));
        playerInventoryCapacitySpinner.setPreferredSize(new Dimension(90,24));
        playerInventoryCapacitySpinner.setMinimumSize(new Dimension(90,24));
        playerInventoryCapacitySpinner.setMaximumSize(new Dimension(90,24));
        playerInventoryCapacitySpinner.addChangeListener(e->{int requested=Math.max(1,Math.min(60,((Number)playerInventoryCapacitySpinner.getValue()).intValue()));int old=playerInventoryCapacity;setInventoryCapacity(requested);if(playerInventoryCapacity!=requested)playerInventoryCapacitySpinner.setValue(old);});
        capacityRow.add(playerInventoryCapacitySpinner);inventoryHudPanel.add(capacityRow);
        JPanel positionRow=new JPanel(new FlowLayout(FlowLayout.LEFT,4,2));positionRow.add(new JLabel("Inventory position:"));
        playerInventoryPositionCombo=new JComboBox<>(new String[]{"Bottom","Side"});playerInventoryPositionCombo.setSelectedIndex(Math.max(0,Math.min(1,playerInventoryPosition)));
        playerInventoryPositionCombo.addActionListener(e->playerInventoryPosition=Math.max(0,playerInventoryPositionCombo.getSelectedIndex()));positionRow.add(playerInventoryPositionCombo);inventoryHudPanel.add(positionRow);
        addControlComponent(ctrlContent,inventoryHudPanel);

        // Object Behavior, Action Builder, and Behavior Tree controls are now
        // managed from the selected object's Properties -> Behavior tab.

        // OBJ objects and light sources are created from the Object Inspector.
        // The old creation buttons were removed here to keep World/Project/Environment
        // Settings focused on global project and environment configuration.

        // ------------------------------------------------------------
        // SCENE TRIGGER CONTROLS
        // ------------------------------------------------------------
        // Scene triggers are editor objects: they have their own selection,
        // transform, size, destination and delete controls. A trigger is
        // created only by the explicit button below.
        JButton btnCreateSceneTrigger = new JButton("🌀 Create Scene Trigger");
        btnCreateSceneTrigger.setToolTipText(
                "Create one scene trigger at the player's current position"
        );

        JPanel sceneTriggerDestinationRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 2));
        sceneTriggerDestinationRow.add(new JLabel("Warp To Scene:"));
        JComboBox<String> sceneTriggerDestinationCombo = new JComboBox<>();
        sceneTriggerDestinationCombo.setPrototypeDisplayValue("Select Destination Scene");
        sceneTriggerDestinationRow.add(sceneTriggerDestinationCombo);

        JLabel sceneTriggerSelectionLabel = new JLabel("Scene Trigger: not selected");

        JPanel sceneTriggerSizeRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 2));
        sceneTriggerSizeRow.add(new JLabel("W:"));
        JSpinner sceneTriggerWidthSpinner = new JSpinner(
                new SpinnerNumberModel(2.0, 0.1, 1000.0, 0.1)
        );
        sceneTriggerSizeRow.add(sceneTriggerWidthSpinner);
        sceneTriggerSizeRow.add(new JLabel("H:"));
        JSpinner sceneTriggerHeightSpinner = new JSpinner(
                new SpinnerNumberModel(2.5, 0.1, 1000.0, 0.1)
        );
        sceneTriggerSizeRow.add(sceneTriggerHeightSpinner);
        sceneTriggerSizeRow.add(new JLabel("D:"));
        JSpinner sceneTriggerDepthSpinner = new JSpinner(
                new SpinnerNumberModel(0.5, 0.1, 1000.0, 0.1)
        );
        sceneTriggerSizeRow.add(sceneTriggerDepthSpinner);

        Runnable refreshSceneTriggerControls = () -> {
            refreshingSceneTriggerControls = true;
            try {
                sceneTriggerDestinationCombo.removeAllItems();
                for (int i = 0; i < timelineScenes.size(); i++) {
                    String name = timelineScenes.get(i).getProperty(
                            "scene.name", "Scene " + i
                    );
                    sceneTriggerDestinationCombo.addItem(i + ": " + name);
                }

                // IMPORTANT: refreshing the scene list or destination combo must
                // never change which object is selected. A trigger is selected
                // only when the normal Selected Object Index points at the
                // trigger's virtual object index.
                int index = getSelectedSceneTriggerIndex();
                SceneTrigger trigger = index >= 0 && index < sceneTriggers.size()
                        ? sceneTriggers.get(index) : null;

                sceneTriggerSelectionLabel.setText(index >= 0
                        ? "Scene trigger selected (object " + selectedObjectIndex + ")"
                        : "Scene trigger: not selected");

                // The Warp To Scene control is selection-sensitive. It must
                // always reflect the destination stored on the currently
                // selected trigger, and it must not retain the previous
                // trigger's destination when a normal object (or nothing) is
                // selected. Each SceneTrigger owns its own destinationScene.
                sceneTriggerDestinationCombo.setEnabled(trigger != null
                        && sceneTriggerDestinationCombo.getItemCount() > 0);

                if (trigger == null) {
                    sceneTriggerDestinationCombo.setSelectedIndex(-1);
                    sceneTriggerWidthSpinner.setValue(2.0);
                    sceneTriggerHeightSpinner.setValue(2.5);
                    sceneTriggerDepthSpinner.setValue(0.5);
                    // No trigger selected means there is no destination to
                    // display. Never fall back to the current scene, because
                    // that makes the dropdown appear to belong to a trigger
                    // that is not selected.
                    sceneTriggerDestinationCombo.setSelectedIndex(-1);
                } else {
                    sceneTriggerWidthSpinner.setValue((double) trigger.width);
                    sceneTriggerHeightSpinner.setValue((double) trigger.height);
                    sceneTriggerDepthSpinner.setValue((double) trigger.depth);
                    if (sceneTriggerDestinationCombo.getItemCount() > 0) {
                        int destination = Math.max(0, Math.min(
                                trigger.destinationScene,
                                sceneTriggerDestinationCombo.getItemCount() - 1
                        ));
                        sceneTriggerDestinationCombo.setSelectedIndex(destination);
                    }
                }
            } finally {
                refreshingSceneTriggerControls = false;
            }
        };

        // Keep the destination list synchronized with the Timeline Editor and
        // with any other code that adds/renames scenes in timelineScenes. This
        // mirrors the automatic dialogue-topic refresh behavior: the combo is
        // rebuilt only when the scene list actually changes.
        sceneTriggerDestinationRefreshHook = () -> {
            if (SwingUtilities.isEventDispatchThread()) {
                refreshSceneTriggerControls.run();
            } else {
                SwingUtilities.invokeLater(refreshSceneTriggerControls);
            }
        };

        Timer sceneTriggerDestinationRefreshTimer = new Timer(750, e -> {
            StringBuilder signatureBuilder = new StringBuilder();
            for (int i = 0; i < timelineScenes.size(); i++) {
                Properties scene = timelineScenes.get(i);
                signatureBuilder.append(i).append(':')
                        .append(scene.getProperty("scene.name", "Scene " + i))
                        .append('|');
            }
            String signature = signatureBuilder.toString();
            if (refreshSceneTriggerDestinationsRequested
                    || !signature.equals(sceneTriggerDestinationSignature)) {
                sceneTriggerDestinationSignature = signature;
                refreshSceneTriggerDestinationsRequested = false;
                refreshSceneTriggerControls.run();
            }
        });
        sceneTriggerDestinationRefreshTimer.setRepeats(true);
        sceneTriggerDestinationRefreshTimer.setInitialDelay(250);
        sceneTriggerDestinationRefreshTimer.start();

        btnCreateSceneTrigger.addActionListener(e -> {
            createSceneTriggerFromInspector();
            refreshSceneTriggerControls.run();
        });

        sceneTriggerDestinationCombo.addActionListener(e -> {
            if (refreshingSceneTriggerControls) return;
            SceneTrigger trigger = getSelectedSceneTrigger();
            if (trigger != null && sceneTriggerDestinationCombo.getSelectedIndex() >= 0) {
                // Store the selected scene on this exact trigger instance.
                // Do not use a global/current-scene destination.
                trigger.destinationScene = sceneTriggerDestinationCombo.getSelectedIndex();
            }
        });

        JButton btnDeleteSceneTrigger =
                new JButton("⛔ Delete Selected Scene Trigger");
        btnDeleteSceneTrigger.addActionListener(e -> {
            int index = getSelectedSceneTriggerIndex();
            if (index >= 0 && index < sceneTriggers.size()) {
                sceneTriggers.remove(index);
                selectedObjectIndex = sceneTriggers.isEmpty()
                        ? -1
                        : spawnedObjects.size() + Math.min(index, sceneTriggers.size() - 1);
                refreshSelectedObjectSelector();
                refreshProjectileObjectCombo();
                refreshSceneTriggerControls.run();
            }
        });

     //   addControlComponent(ctrlContent, btnCreateSceneTrigger);
        //addControlComponent(ctrlContent, sceneTriggerSizeRow);
      //  addControlComponent(ctrlContent, btnDeleteSceneTrigger);

        refreshSceneTriggerControls.run();

        // ------------------------------------------------------------
        // SELECTED LIGHT SOURCE CONTROLS
        // ------------------------------------------------------------
        // Light color, intensity, and radius are configured exclusively in
        // Object Properties -> Light. They are intentionally not duplicated
        // in World/Environment Settings.

