        JPanel lightingStrengthPanel = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 2));
        lightingStrengthPanel.setAlignmentX(Component.LEFT_ALIGNMENT);

        lightingStrengthPanel.add(
                new JLabel("Lighting Strength:")
        );

        JSpinner lightingStrengthSpinner =
                new JSpinner(
                        new SpinnerNumberModel(
                                0.55,
                                0.0,
                                1.0,
                                0.05
                        )
                );

        lightingStrengthSpinner.setPreferredSize(new Dimension(90, 24));
        lightingStrengthSpinner.setMinimumSize(new Dimension(90, 24));
        /* Compact, left-aligned editor control. */
        lightingStrengthSpinner.addChangeListener(e ->
                dynamicLightingStrength =
                        ((Number)
                                lightingStrengthSpinner.getValue())
                                .floatValue()
        );

        lightingStrengthPanel.add(lightingStrengthSpinner);
        addControlComponent(ctrlContent, lightingStrengthPanel);

        // ========================================================
        // WORLD RENDERING OPTIONS
        // ========================================================

        JPanel renderingPanel = new JPanel();
        renderingPanel.setLayout(new BoxLayout(renderingPanel, BoxLayout.Y_AXIS));
        renderingPanel.setAlignmentX(Component.LEFT_ALIGNMENT);

        objectShadowsCheckBox = new JCheckBox("Enable Object Shadows", objectShadowsEnabled);
        objectShadowsCheckBox.setAlignmentX(Component.LEFT_ALIGNMENT);
        objectShadowsCheckBox.setToolTipText("Render soft projected shadows underneath the player and scene objects.");
        objectShadowsCheckBox.addActionListener(e -> objectShadowsEnabled = objectShadowsCheckBox.isSelected());
        renderingPanel.add(objectShadowsCheckBox);

        sceneFogCheckBox = new JCheckBox("Enable Fog", sceneFogEnabled);
        sceneFogCheckBox.setAlignmentX(Component.LEFT_ALIGNMENT);
        sceneFogCheckBox.setToolTipText("Apply distance-based atmospheric fog to the 3D scene.");
        renderingPanel.add(sceneFogCheckBox);

        JPanel fogLevelRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 2));
        fogLevelRow.setAlignmentX(Component.LEFT_ALIGNMENT);
        String[] fogLevels = {"Light", "Medium", "Heavy", "Very Heavy"};
        fogLevelRow.add(new JLabel("Fog Level:"));
        sceneFogLevelCombo = new JComboBox<>(fogLevels);
        sceneFogLevelCombo.setSelectedIndex(Math.max(0, Math.min(3, sceneFogLevel)));
        sceneFogLevelCombo.setEnabled(sceneFogEnabled);
        sceneFogLevelCombo.setToolTipText("Choose the density of the scene fog.");
        sceneFogLevelCombo.addActionListener(e -> sceneFogLevel = Math.max(0, sceneFogLevelCombo.getSelectedIndex()));
        fogLevelRow.add(sceneFogLevelCombo);
        renderingPanel.add(fogLevelRow);

        sceneFogCheckBox.addActionListener(e -> {
            sceneFogEnabled = sceneFogCheckBox.isSelected();
            sceneFogLevelCombo.setEnabled(sceneFogEnabled);
        });
        addControlComponent(ctrlContent, renderingPanel);

        // ========================================================
        // HEIGHTMAP EDITOR
        // ========================================================

        JButton btnHeightmapsEditor = new JButton("🌋 Open Heightmaps Editor");
        btnHeightmapsEditor.setToolTipText("Open the Heightmaps editor in the already-initialized WorldsGL JVM");
        btnHeightmapsEditor.addActionListener(e -> {
            try {
                // ThirdPersonGameNew has already initialized JOGL before the
                // control panel is created. Opening Heightmaps in this same JVM
                // avoids the previous second-JVM GlueGen/NativeWindow mismatch
                // that produced JVMUtil.initialize(ByteBuffer) errors.
                Heightmaps.openEditor();
            } catch (Throwable ex) {
                ex.printStackTrace();
                JOptionPane.showMessageDialog(
                        ctrlFrame,
                        "Could not open Heightmaps Editor.\n\n"
                                + ex.getClass().getName() + ": " + ex.getMessage(),
                        "Heightmaps",
                        JOptionPane.ERROR_MESSAGE
                );
            }
        });
        addControlComponent(ctrlContent, btnHeightmapsEditor);

        // ========================================================
        // HEIGHT BRUSH
        // ========================================================
        // This edits the already-generated heightfield directly. It does not
        // open Heightmaps.java and does not require regenerating the source image.
        JPanel heightBrushPanel = new JPanel(new GridBagLayout());
        heightBrushPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
        heightBrushPanel.setBorder(BorderFactory.createTitledBorder("Height Brush"));

        GridBagConstraints heightBrushGbc = new GridBagConstraints();
        heightBrushGbc.insets = new Insets(2, 4, 2, 4);
        heightBrushGbc.anchor = GridBagConstraints.WEST;

        heightmapHeightBrushButton = new JButton("🌋 Height Brush: OFF");
        heightmapHeightBrushButton.setToolTipText("Paint the generated heightmap up or down directly in the viewport.");
        heightmapHeightBrushButton.addActionListener(e ->
                setHeightmapHeightBrushEnabled(!heightmapHeightBrushEnabled));
        heightBrushGbc.gridx = 0;
        heightBrushGbc.gridy = 0;
        heightBrushGbc.gridwidth = 3;
        heightBrushPanel.add(heightmapHeightBrushButton, heightBrushGbc);
        heightBrushGbc.gridwidth = 1;

