    /**
     * Keeps each settings control at its natural preferred height so
     * buttons and labels are not stretched by the surrounding layout.
     */
    private ImageIcon loadWGANIMButtonIcon() {
        try {
            ArrayList<File> candidates = new ArrayList<>();
            try {
                File codeSource = new File(ThirdPersonGameNew.class.getProtectionDomain()
                        .getCodeSource().getLocation().toURI());
                File base = codeSource.isFile() ? codeSource.getParentFile() : codeSource;
                if (base != null) candidates.add(new File(base, "wganim.ico"));
            } catch (Throwable ignored) {}
            candidates.add(new File(System.getProperty("user.dir"), "wganim.ico"));
            candidates.add(new File("wganim.ico"));

            for (File f : candidates) {
                if (f != null && f.isFile()) {
                    BufferedImage img = ImageIO.read(f);
                    if (img != null) {
                        int size = 24;
                        BufferedImage scaled = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
                        Graphics2D g = scaled.createGraphics();
                        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
                        g.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
                        g.drawImage(img, 0, 0, size, size, null);
                        g.dispose();
                        return new ImageIcon(scaled);
                    }
                }
            }
        } catch (Throwable ignored) {}
        return null;
    }

    private void addControlComponent(
            JPanel panel,
            Component component
    ) {
        if (component instanceof JComponent) {
            ((JComponent) component).setAlignmentX(Component.LEFT_ALIGNMENT);
        }

        Dimension preferred = component.getPreferredSize();
        component.setMaximumSize(
                new Dimension(
                        Math.max(1, preferred.width),
                        Math.max(1, preferred.height)
                )
        );

        panel.add(component);
        panel.add(Box.createVerticalStrut(4));
    }


    // ============================================================
    // SKYBOX COLOR ANALYSIS
    // ============================================================

    /**
     * Calculates a representative RGB color for the selected skybox.
     * A sampled average is used so very large skybox images do not cause
     * unnecessary work when the texture is selected.
     */
    private float[] calculateAverageImageColor(String path) {

        try {
            java.awt.image.BufferedImage image =
                    ImageIO.read(new File(path));

            if (image == null) {
                return null;
            }

            int width = image.getWidth();
            int height = image.getHeight();

            // Sample at most about 10,000 pixels.
            int stepX = Math.max(1, width / 100);
            int stepY = Math.max(1, height / 100);

            double r = 0.0;
            double g = 0.0;
            double b = 0.0;
            long count = 0;

            for (int y = 0; y < height; y += stepY) {
                for (int x = 0; x < width; x += stepX) {

                    int argb = image.getRGB(x, y);

                    int alpha = (argb >>> 24) & 0xFF;
                    if (alpha < 16) {
                        continue;
                    }

                    float pr = ((argb >> 16) & 0xFF) / 255.0f;
                    float pg = ((argb >> 8) & 0xFF) / 255.0f;
                    float pb = (argb & 0xFF) / 255.0f;

                    // Do not let almost-black pixels dominate the hue.
                    float luminance =
                            0.2126f * pr +
                            0.7152f * pg +
                            0.0722f * pb;

                    if (luminance < 0.025f) {
                        continue;
                    }

                    r += pr * 255.0;
                    g += pg * 255.0;
                    b += pb * 255.0;
                    count++;
                }
            }

            if (count == 0) {
                return null;
            }

            return new float[] {
                    (float) (r / count / 255.0),
                    (float) (g / count / 255.0),
                    (float) (b / count / 255.0)
            };

        } catch (IOException ex) {
            System.err.println(
                    "Could not analyze skybox color: "
                    + ex.getMessage()
            );
            return null;
        }
    }

    // ============================================================
