    private String chooseTextureFile() {

        JFileChooser chooser =
                new JFileChooser();

        FileNameExtensionFilter filter =
                new FileNameExtensionFilter(
                        "Image Files",
                        "png",
                        "jpg",
                        "jpeg",
                        "bmp",
                        "gif"
                );

        chooser.setFileFilter(
                filter
        );

        int returnVal =
                chooser.showOpenDialog(
                        null
                );

        if (returnVal ==
                JFileChooser.APPROVE_OPTION) {

            return chooser
                    .getSelectedFile()
                    .getAbsolutePath();
        }

        return null;
    }

